comms.text:
@1 וּשְׁמַע יִתְרוֹ רַבָּא דְמִדְיָן חֲמוּהִי דְמשֶׁה יַת כָּל דִי עֲבַד יְיָ לְמשֶׁה וּלְיִשְׂרָאֵל עַמֵהּ אֲרֵי אַפִּיק יְיָ יָת יִשְׂרָאֵל מִמִצְרָיִם:
@2 וּדְבַר יִתְרוֹ חֲמוּהִי דְמשֶׁה יָת צִפֹּרָה אִתַּת משֶׁה בָּתַר דְפַטְרַהּ:
@3 וְיָת תְּרֵין בְּנָהָא דִי שׁוּם חַד גֵרְשֹׁם אֲרֵי אֲמַר דַיָר הֲוֵיתִי בְּאַרְעָא נוּכְרָאָה:
@4 וְשׁוּם חַד אֱלִיעֶזֶר אֲרֵי אֱלָהָא דְאַבָּא הֲוָה בְסַעְדִי וְשֵׁזְבַנִי מֵחַרְבָּא דְפַרְעֹה:
@5 וַאֲתָא יִתְרוֹ חֲמוּהִי דְמשֶׁה וּבְנוֹהִי וְאִתְּתֵהּ לְוָת משֶׁה לְמַדְבְּרָא דִי הוּא שָׁרֵי תַמָן לְטוּרָא דְאִתְגְלֵי עֲלוֹהִי יְקָרָא דַיְיָ:
@6 וַאֲמַר לְמשֶׁה אֲנָא חֲמוּךְ יִתְרוֹ אָתֵי לְוָתָךְ וְאִתְּתָךְ וּתְרֵין בְּנָהָא עִמַהּ:
@7 וּנְפַק משֶׁה לְקַדָמוּת חֲמוּהִי וּסְגִיד וּנְשִׁיק לֵהּ וּשְׁאִילוּ גְבַר לְחַבְרֵהּ לִשְׁלָם וְעַלוּ לְמַשְׁכְּנָא:
@8 וְאִשְׁתָּעִי משֶׁה לַחֲמוּהִי יָת כָּל דִי עֲבַד יְיָ לְפַרְעֹה וּלְמִצְרָאֵי עַל עֵסַק יִשְׂרָאֵל יָת כָּל עַקְתָא דִי אַשְׁכַּחְתִּנוּן בְּאָרְחָא וְשֵׁזְבָנוּן יְיָ:
@9 וַחֲדִי יִתְרוֹ עַל כָּל טַבְתָא דִי עֲבַד יְיָ לְיִשְׂרָאֵל דִי שֵׁזְבָנוּן מִידָא דְמִצְרָאֵי:
@10 וַאֲמַר יִתְרוֹ בְּרִיךְ יְיָ דִי שֵׁזִיב יָתְכוֹן מִידָא דְמִצְרָאֵי וּמִידָא דְפַרְעֹה דִי שֵׁזִיב יָת עַמָא מִתְּחוֹת מַרְוַת מִצְרָאֵי:
@11 כְּעַן יְדַעְנָא אֲרֵי רַב יְיָ וְלֵית אֱלָּהּ בַּר מִנֵהּ אֲרֵי בְּפִתְגָמָא דִי חַשִׁיבוּ מִצְרָאֵי לְמִדַן יָת יִשְׂרָאֵל בֵּהּ דָנִנוּן:
@12 וְקָרִיב יִתְרוֹ חֲמוּהִי דְמשֶׁה עֲלָוָן וְנִכְסַת קוּדְשִׁין קֳדָם יְיָ וַאֲתָא אַהֲרֹן וְכֹל סָבֵי יִשְׂרָאֵל לְמֵיכַל לַחְמָא עִם חֲמוּהִי דְמשֶׁה קֳדָם יְיָ:
@13 וַהֲוָה מִיוֹמָא דְבַתְרוֹהִי וִיתֵיב משֶׁה לְמִדַן יָת עַמָא וְקָם עַמָא עִלָוֹהִי דְמשֶׁה מִן צַפְרָא עַד רַמְשָׁא:
@14 וַחֲזָא חֲמוּהִי דְמשֶׁה יָת כָּל דִי הוּא עָבֵד לְעַמָא וַאֲמַר מָא פִתְגָמָא הָדֵין דִי אַתְּ עָבֵד לְּעַמָא מָה דֵין אַתְּ יָתֵב בִּלְחוֹדָךְ וְכָל עַמָא קָיְמִין עִלָוָךְ מִן צַפְרָא עַד רַמְשָׁא:
@15 וַאֲמַר משֶׁה לַחֲמוּהִי אֲרֵי אָתָן לְוָתִי עַמָא לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ:
@16 כַּד הֲוֵי לְהוֹן דִינָא אָתָן לְוָתִי וְדָאִינְנָא בֵּין גַבְרָא וּבֵין חַבְרֵהּ וּמְהוֹדַעְנָא לְהוֹן יָת קְיָמַיָא דַיְיָ וְיָת אוֹרָיָתֵהּ:
@17 וַאֲמַר חֲמוּהִי דְמשֶׁה לֵהּ לָא תַקִין פִּתְגָמָא דְאַתְּ עָבֵד:
@18 מִלְאָה תִלְאֶה אַף אַתְּ אַף עַמָא הָדֵין דִעִמָךְ אֲרֵי יַקִיר מִנָךְ פִּתְגָמָא לָא תִכּוֹל לְמֶעְבְּדֵהּ בִּלְחוֹדָךְ:
@19 כְּעַן קַבֵּל מִנִי אֲמַלְכִנָךְ וִיהֵי מֵימְרָא דַיְיָ בְּסַעְדָךְ הֱוֵי אַתְּ לְעַמָא (תְּבַע) אוּלְפַן מִן קֳדָם יְיָ וּתְהֵי מַיְתִי אַתְּ יָת פִּתְגָמַיָא לִקֳדָם יְיָ:
@20 וְתַזְהַר יָתְהוֹן יָת קְיָמַיָא וְיָת אוֹרַיְתָא וּתְהוֹדַע לְהוֹן יָת אוֹרְחָא דִיְהָכוּן בַּהּ וְיָת עוֹבָדָא דִיַעְבְּדוּן:
@21 וְאַתְּ תֶּחֶזֵי מִכָּל עַמָא גֻבְרִין דְחֵילָא דַחֲלַיָא דַיְיָ גֻבְרִין דִקְשׁוֹט דְסָנָן לְקַבָּלָא מָמוֹן וּתְמַנֵי עֲלֵיהוֹן רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@22 וִידוּנוּן יָת עַמָא בְּכָל עִדַן וִיהֵי כָּל פִּתְגַם רַב יַיְתוּן לְוָתָךְ וְכָל פִּתְגַם זְעֵיר יְדוּנוּן אִנוּן וְיִקְלוּן מִנָךְ וִיסוֹבְרוּן עִמָךְ:
@23 אִם יָת פִּתְגָמָא הָדֵין תַּעְבֵּד וִיפַקְדִנָךְ יְיָ וְתִכּוֹל לְמֵיקָם וְאַף כָּל עַמָא הָדֵין עַל אַתְרֵהּ יְהַךְ בִּשְׁלָם:
@24 וְקַבִּיל משֶׁה לְמֵימְרָא דַחֲמוּהִי וַעֲבַד כֹּל דִי אֲמָר:
@25 וּבְחַר משֶׁה גֻבְרִין דְחֵילָא מִכָּל יִשְׂרָאֵל וּמַנִי יָתְהוֹן רֵישִׁין עַל עַמָא רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@26 וְדַיְנִין יָת עַמָא בְּכָל עִדָן יָת פִתְגַם קָשֵׁי מַיְתִין לְוָת משֶׁה וְכָל פִּתְגַם זְעֵיר דָיְנִין אִנוּן:
@27 וְשַׁלַח משֶׁה יָת חֲמוּהִי וַאֲזַל לֵהּ לְאַרְעֵהּ:
@28 בְּיַרְחָא תְּלִיתָאָה לְמִפַּק בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם בְּיוֹמָא הָדֵין אֲתוֹ לְמַדְבְּרָא דְסִינָי:
@29 וּנְטָלוּ מֵרְפִידִים וַאֲתוֹ לְמַדְבְּרָא דְסִינָי וּשְׁרוֹ בְּמַדְבְּרָא וּשְׁרָא תַמָן יִשְׂרָאֵל לָקֳבֵל טוּרָא:
@30 וּמשֶׁה סְלֵק לִקֳדָם יְיָ וּקְרָא לֵהּ יְיָ מִן טוּרָא לְמֵימַר כִּדְנַן תֵּימַר לְבֵית יַעֲקֹב וּתְחַוִי לִבְנֵי יִשְׂרָאֵל:
@31 אַתּוּן חֲזִתּוּן דִי עֲבָדִית לְמִצְרָיִם וּנְטָלִית (נ''א וְאַטְּלִית) יָתְכוֹן כִּדְעַל גַדְפֵי נִשְׁרִין וְקָרֵבִית יָתְכוֹן לְפָלְחָנִי:
@32 וּכְעַן אִם קַבָּלָא תְקַבְּלוּן לְמֵימְרִי וְתִטְרוּן יָת קְיָמִי וּתְהוֹן קֳדָמַי חַבִּיבִין מִכָּל עַמְמַיָא אֲרֵי דִי לִי כָּל אַרְעָא:
@33 וְאַתּוּן תְּהוֹן קֳדָמַי מַלְכִין כָּהֲנִין וְעַם קַדִישׁ אִלֵין פִּתְגָמַיָא דִי תְמַלֵל עִם בְּנֵי יִשְׂרָאֵל:
@34 וַאֲתָא משֶׁה וּקְרָא לְסָבֵי עַמָא וְסַדַר קֳדָמֵיהוֹן יָת כָּל פִּתְגָמַיָא הָאִלֵין דִפַקְדֵיהּ יְיָ:
@35 וַאֲתִיבוּ כָל עַמָא כַּחֲדָא וַאֲמָרוּ כֹּל דִי מַלִיל יְיָ נַעְבֵּד וַאֲתֵיב משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@36 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מִתְגְלִי לָךְ בְּעֵיבָא דַעֲנָנָא בְּדִיל דְיִשְׁמַע עַמָא בְּמַלָלוּתִי עִמָךְ וְאַף בָּךְ יְהֵימְנוּן לְעָלָם וְחַוִי משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@37 וַאֲמַר יְיָ לְמשֶׁה אִזֵיל לְוָת עַמָא וּתְזַמִנוּן יוֹמָא דֵין וּמְחָר וִיחַוְרוּן לְבוּשֵׁיהוֹן:
@38 וִיהוֹן זְמִינִין לְיוֹמָא תְלִיתָאָה אֲרֵי בְּיוֹמָא תְלִיתָאָה יִתְגְלִי יְיָ לְעֵינֵי כָל עַמָא עַל טוּרָא דְסִינָי:
@39 וּתְתַחֵם יָת עַמָא סְחוֹר סְחוֹר לְמֵימַר אִסְתַּמָרוּ לְכוֹן מִלְמִסַק בְּטוּרָא וּלְמִקְרַב בְּסוֹפֵהּ כָּל דְיִקְרַב בְּטוּרָא אִתְקְטָלָא יִתְקְטֵל:
@40 לָא תִקְרַב בֵּהּ יְדָא אֲרֵי אִתְרְגָמָא יִתְרְגֵם אוֹ אִשְׁתְּדָאָה יִשְׁתְּדִי אִם בְּעִירָא אִם אֱנָשָׁא לָא יִתְקַיָם בְּמֵיגַד שׁוֹפָרָא אִנוּן מְרָשָׁן לְמִסַק בְּטוּרָא:
@41 וּנְחַת משֶׁה מִן טוּרָא לְוָת עַמָא וְזַמִין יָת עַמָא וְחַוָרוּ לְבוּשֵׁיהוֹן:
@42 וַאֲמַר לְעַמָא הֱווֹ זְמִינִין לִתְלָתָא יוֹמִין לָא תִקְרְבוּן לְצַד אִתְּתָא:
@43 וַהֲוָה בְיוֹמָא תְלִיתָאָה בְּמֶהֱוֵי צַפְרָא וַהֲוָה קָלִין וּבַרְקִין וַעֲנָנָא תַקִיף עַל טוּרָא וְקַל שׁוֹפָרָא תַּקִיף לַחֲדָא וְזָע כָּל עַמָא דִי בְמַשְׁרִיתָא:
@44 וְאַפֵיק משֶׁה יָת עַמָא לְקַדָמוּת מֵימְרָא דַיְיָ מִן מַשְׁרִיתָא וְאִתְעַתָּדוּ בְּשִׁפּוֹלֵי טוּרָא:
@45 וְטוּרָא דְסִינַי תָּנַן כֻּלֵהּ מִן קֳדָם דְאִתְגְלִי עֲלוֹהִי יְיָ בְּאֶשָׁתָא וּסְלִיק תְּנָנֵהּ כִּתְנָנָא דְאַתּוּנָא וְזָע כָּל טוּרָא לַחֲדָא:
@46 וַהֲוָה קַל שׁוֹפָרָא אָזֵל וְתָקֵף לַחֲדָא משֶׁה מְמַלֵל וּמִן קֳדָם יְיָ מִתְעֲנֵי לֵהּ בְקָל:
@47 וְאִתְגְלִי יְיָ עַל טוּרָא דְסִינַי לְרֵישׁ טוּרָא וּקְרָא יְיָ לְמשֶׁה לְרֵישׁ טוּרָא וּסְלִיק משֶׁה:
@48 וַאֲמַר יְיָ לְמשֶׁה חוּת אַסְהֵיד בְּעַמָא דִילְמָא יְפַגְרוּן קֳדָם יְיָ לְמֶחֱזֵי וְיִפֵּל מִנְהוֹן סַגִי:
@49 וְאַף כָּהֲנַיָא דִקְרִיבִין לְשַׁמָשָׁא קֳדָם יְיָ יִתְקַדְשׁוּן דִילְמָא יִקְטוֹל בְּהוֹן יְיָ:
@50 וַאֲמַר משֶׁה קֳדָם יְיָ לָא יִכּוֹל עַמָא לְמִסַק לְטוּרָא דְסִינַי אֲרֵי אַתְּ אַסְהֵדְתָּ בָּנָא לְמֵימַר תַּחִים יָת טוּרָא וְקַדְשֵׁהּ:
@51 וַאֲמַר לֵהּ יְיָ אִזֵיל חוּת וְתִסַק אַתְּ וְאַהֲרֹן עִמָךְ וְכָהֲנַיָא וְעַמָא לָא יְפַגְרוּן לְמִסַק לִקֳדָם יְיָ דִילְמָא יִקְטוֹל בְּהוֹן:
@52 וּנְחַת משֶׁה לְעַמָא וַאֲמַר לְהוֹן:
@53 וּמַלִיל יְיָ יָת כָּל פִּתְגָמַיָא הָאִלֵין לְמֵימָר:
@54 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּיקְתָּךְ מֵאַרְעָא דְמִ צְרַיִם מִבֵּית עַבְדוּתָא:
@55 לָא יְהֵי לָךְ אֱלָהּ אָחֳרָן בַּר מִנִי:
@56 לָא תַעְבֵּד לָךְ צֶלֶם וְכָל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@57 לָא תִסְגֻד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מָרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשָׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵי בָּתַר אֲבָהָתְהוֹן:
@58 וְעָבֵד טִּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְרֵי פִקוֹדָי:
@59 לָא תֵימֵי יָת שְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יִזַכֵּי יְיָ יָת דִיֵימֵי בִשְׁמֵהּ לְשִׁקְרָא:
@60 הֲוֵי דְכִיר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ:
@61 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@62 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עִבִדְתָּא אַתְּ וּבְרָךְ וּבְרַתָּךְ עַבְדָךְ וְאַמְתָךְ וּבְעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ:
@63 אֲרֵי שִׁתָּא יוֹמִין עֲבַד יְיָ יָת שְׁמַיָא וְיָת אַרְעָא יָת יַמָא וְיָת כָּל דִי בְהוֹן וְנָח בְּיוֹמָא שְׁבִיעָאָה עַל כֵּן בָּרִיךְ יְיָ יָת יוֹמָא דְשַׁבְּתָא וְקַדְשֵׁהּ:
@64 יַקַר יָת אָבוּךְ וְיָת אִמָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@65 לָא תִקְטוֹל נְפָשׁ לָא תְגוּף לָא תִגְנוּב לָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@66 לָא תַחְמֵד בֵּית חַבְרָךְ לָא תַחְמֵד אִתַּת חַבְרָךְ וְעַבְדֵהּ וְאַמְתֵהּ וְתוֹרֵהּ וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@67 וְכָל עַמָא חָזָן יָת קָלַיָא וְיָת בָּעוֹרַיָא וְיָת קַל שׁוֹפָרָא וְיָת טוּרָא תָּנֵן וַחֲזָא עַמָא וְזָעוּ וְקָמוּ מֵרָחִיק:
@68 וַאֲמָרוּ לְמשֶׁה מַלֵל אַתְּ עִמָנָא וּנְקַבֵּל וְלָא יִתְמַלֵל עִמָנָא מִן קֳדָם יְיָ דִילְּמָא נְמוּת:
@69 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אֲרֵי בְּדִיל לְנַסָאָה יָתְכוֹן אִתְגְלִי לְכוֹן יְקָרָא דַיְיָ וּבְדִיל דִתְהֵי דַחַלְתֵּהּ עַל אַפֵּיכוֹן בְּדִיל דְלָא תְחוּבוּן:
@70 וְקָם עַמָא מֵרָחִיק וּמשֶׁה קָרֵב לְצַד אַמִיטְּתָא דִתַמָן יְקָרָא דַיְיָ:
@71 וַאֲמַר יְיָ לְמשֶׁה כִּדְנַן תֵּימַר לִבְנֵי יִשְׂרָאֵל אַתּוּן חֲזִיתּוּן אֲרֵי מִן שְׁמַיָא מַלֵילִית עִמְכוֹן:
@72 לָא תַעְבְּדוּן קֳדָמָי דַחֲלָן דִכְסַף וְדַחֲלָן דִדְהַב לָא תַעְבְּדוּן לְכוֹן:
@73 מַדְבַּח אַדְמְתָא תַּעְבֵּד קֳדָמַי וּתְהֵי דַבָּח עֲלוֹהִי יָת עֲלָוָתָךְ וְיָת נְכַס קוּדְשָׁךְ מִן עָנָךְ וּמִן תּוֹרָךְ בְּכָל אַתְרָא דִי אַשְׁרֵי יָת שְׁכִנְתִּי לְתַמָן אֶשְׁלַח בִּרְכְּתִי לָךְ וֶאֱבָרֵכִנָךְ:
@74 וְאִם מַדְבַּח אַבְנִין תַּעְבֵּד קֳדָמַי לָא תִבְנֵי יָתְהוֹן פְּסִילָן לָא תְרִים חַרְבָּךְ עֲלַהּ וּתְחַלְלִנַהּ:
@75 וְלָא תִסַק בְּדַרְגִין עַל מַדְבְּחִי דְלָא תִתְגְלֵי עֶרְיְתָךְ עֲלוֹהִי: פפפ:

@1 **וישמע יתרו.** מה שמועה שמע ובא, קריעת ים סוף ומלחמת עמלק: **יתרו.** שבע שמות נקראו לו רעואל, יתר, יתרו, חובב, חבר, קני, פוטיאל. יתר, על שם שיתר פרשה אחת בתורה (להלן פסוק כא) ואתה תחזה. יתרו לכשנתגיר וקים המצות הוסיפו לו אות אחת על שמו. חובב שחבב את התורה. וחובב הוא יתרו, שנאמר (שופטים ד יא) מבני חובב חותן משה. ויש אומרים רעואל אביו של יתרו היה, ומה הוא אומר (שמות ב יח) ותבאנה אל רעואל אביהן, שהתינוקות קורין לאבי אביהן אבא. בספרי: **חתן משה.** כאן היה יתרו מתכבד במשה, אני חותן המלך ולשעבר היה משה תולה הגדלה בחמיו, שנאמר (שמות ד יח) וישב אל יתר חותנו: **למשה ולישראל.** שקול משה כנגד כל ישראל: **את כל אשר עשה.** להם בירידת המן ובבאר ובעמלק: **כי הוציא ה'** וגו' **.** זו גדולה על כלם:
@2 **אחר שלוחיה.** כשאמר לו הקדוש ברוך הוא במדין (שמות ד יט) לך שוב מצרים, (שם כ) ויקח משה את אשתו ואת בניו גו' ויצא אהרן לקראתו, (שם כז) ויפגשהו בהר האלהים. אמר לו מי הם הללו. אמר לו זו היא אשתי שנשאתי במדין ואלו בני. אמר לו והיכן אתה מוליכן. אמר לו למצרים. אמר לו על הראשונים אנו מצטערים ואתה בא להוסיף עליהם. אמר לה לכי אל בית אביך, נטלה שני בניה והלכה לה:
@4 **ויצלני מחרב פרעה.** כשגלו דתן ואבירם על דבר המצרי ובקש להרג את משה, נעשה צוארו כעמוד של שיש:
@5 **אל המדבר.** אף אנו יודעין שבמדבר היו, אלא בשבחו של יתרו דבר הכתוב, שהיה יושב בכבודו של עולם ונדבו לבו לצאת אל המדבר, מקום תהו, לשמוע דברי תורה:
@6 **ויאמר אל משה.** על ידי שליח: **אני חתנך יתרו** וגו' **.** אם אין אתה יוצא בגיני צא בגין אשתך, ואם אין אתה יוצא בגין אשתך צא בגין שני בניה:
@7 **ויצא משה.** כבוד גדול נתכבד יתרו באותה שעה, כיון שיצא משה יצא אהרן נדב ואביהוא, ומי הוא שראה את אלו יוצאין ולא יצא: **וישתחו וישק לו.** איני יודע מי השתחוה למי, כשהוא אומר איש לרעהו, מי הקרוי איש, זה משה, שנאמר (במדבר יב ג) והאיש משה:
@8 **ויספר משה לחתנו.** למשוך את לבו לקרבו לתורה: **את כל התלאה.** שעל הים ושל עמלק: **התלאה.** למ''ד אל''ף מן היסוד של התבה והתי''ו הוא תקון ויסוד הנופל ממנו לפרקים, וכן תרומה, תנופה, תקומה, תנואה:
@9 **ויחד יתרו.** וישמח יתרו, זהו פשוטו ומדרשו נעשה בשרו חדודין חדודין, מצר על אבוד מצרים, הינו דאמרי אינשי גיורא עד עשרה דרי לא תבזי ארמאה באפיה: **על כל הטובה.** טובת המן והבאר והתורה. ועל כלן אשר הצילו מיד מצרים, עד עכשיו לא היה עבד יכול לברוח ממצרים, שהיתה הארץ מסגרת, ואלו יצאו ששים רבוא:
@10 **אשר הציל אתכם מיד מצרים.** אמה קשה: **ומיד פרעה.** מלך קשה: **מתחת יד מצרים.** כתרגומו לשון רדוי ומרות היד שהיו מכבידים עליהם, היא העבודה:
@11 **עתה ידעתי.** מכירו הייתי לשעבר ועכשיו ביותר: **מכל האלהים.** מלמד שהיה מכיר בכל עבודה זרה שבעולם שלא הניח עבודה זרה שלא עבדה: **כי בדבר אשר זדו עליהם.** כתרגומו במים דמו לאבדם והם נאבדו במים: **אשר זדו.** אשר הרשיעו. ורבותינו דרשוהו לשון (בראשית כה כט) ויזד יעקב נזיד, בקדרה אשר בשלו בה, נתבשלו:
@12 **עלה.** כמשמעה שהיא עולה כליל: **וזבחים.** שלמים: **ויבא אהרן** וגו' **.** ומשה היכן הלך, והלא הוא שיצא לקראתו וגרם לו את כל הכבוד, אלא שהיה עומד ומשמש לפניהם: **לפני האלהים.** מכאן שהנהנה מסעודה שתלמידי חכמים מסבין בה כאלו נהנה מזיו השכינה:
@13 **ויהי ממחרת.** מוצאי יום הכפורים היה, כך שנינו בספרי, ומהו ממחרת, למחרת רדתו מן ההר. ועל כרחך אי אפשר לומר אלא ממחרת יום הכפורים, שהרי קודם מתן תורה אי אפשר לומר (פסוק טז) והודעתי את חקי וגו' , ומשנתנה תורה עד יום הכפורים לא ישב משה לשפוט את העם, שהרי בשבעה עשר בתמוז ירד ושבר את הלוחות, ולמחר עלה בהשכמה ושהה שמונים יום וירד ביום הכפורים. ואין פרשה זו כתובה כסדר, שלא נאמר ויהי ממחרת עד שנה שניה, אף לדברי האומר יתרו קדם מתן תורה בא, שלוחו אל ארצו לא היה אלא עד שנה שניה, שהרי נאמר כאן (פסוק כז) וישלח משה את חתנו ומצינו במסע הדגלים שאמר לו משה (במדבר י כט) נוסעים אנחנו אל המקום וגו' , (שם לא) אל נא תעזוב אותנו, ואם זו קדם מתן תורה, מששלחו והלך היכן מצינו שחזר ואם תאמר שם לא נאמר יתרו אלא חובב, ובנו של יתרו היה, הוא חובב הוא יתרו, שהרי כתיב (שופטים ד יא) מבני חובב חותן משה: **וישב משה** וגו' **ויעמד העם.** יושב כמלך וכלן עומדים, והקשה הדבר ליתרו שהיה מזלזל בכבודן של ישראל והוכיחו על כך, שנאמר (פסוק יד) מדוע אתה יושב לבדך וכלם נצבים: **מן הבקר עד הערב.** אפשר לומר כן, אלא כל דין שדן דין אמת לאמתו אפלו שעה אחת, מעלה עליו הכתוב כאלו עוסק בתורה כל היום, וכאלו נעשה שותף להקדוש ברוך הוא במעשה בראשית, שנאמר בו (בראשית א ה) ויהי ערב ויהי בקר יום אחד:
@15 **כי יבא.** כמו כי בא, לשון הוה: **לדרש אלהים.** כתרגומו למתבע אלפן, לשאול תלמוד מפי הגבורה:
@16 **כי יהיה להם דבר בא.** מי שיהיה לו דבר בא אלי:
@17 **ויאמר חתן משה.** דרך כבוד קוראו הכתוב חותנו של מלך:
@18 **נבל תבל.** כתרגומו. ולשונו לשון כמישה פליישטרי''ר בלעז . כמו (ירמיה ח יג) והעלה נבל, (ישעיה לד ד) כנבול עלה מגפן וגו' , שהוא כמוש על ידי חמה ועל ידי קרח, וכחו תש ונלאה: **גם אתה.** לרבות אהרן וחור ושבעים זקנים: **כי כבד ממך.** כבדו רב יותר מכחך:
@19 **איעצך ויהי אלהים עמך.** בעצה, אמר לו צא המלך בגבורה: **היה אתה לעם מול האלהים.** שליח ומליץ בינותם למקום, ושואל משפטים מאתו: **את הדברים.** דברי ריבותם:
@21 **ואתה תחזה.** ברוח הקדש שעליך: **אנשי חיל.** עשירים, שאין צריכין להחניף ולהכיר פנים: **אנשי אמת.** אלו בעלי הבטחה, שהם כדאי לסמוך על דבריהם, שעל ידי כן יהיו דבריהם נשמעין: **שנאי בצע.** ששונאין את ממונם בדין כההיא דאמרינן כל דינא דמפקין ממונא מניה בדינא לאו דינא הוא: **שרי אלפים.** הם היו שש מאות שרים לשש מאות אלף: **שרי מאות.** ששת אלפים היו: **שרי חמשים.** שנים עשר אלף: **ושרי עשרת.** ששים אלף:
@22 **ושפטו.** וידונון, לשון צווי: **והקל מעליך.** דבר זה להקל מעליך. והקל, כמו (שמות ח יא) והכבד את לבו, (מלכים ב ג כד) והכות את מואב, לשון הוה:
@23 **וצוך אלהים ויכלת עמד.** המלך בגבורה אם יצוה אותך לעשות כך תוכל עמוד, ואם יעכב על ידך לא תוכל לעמוד: **וגם כל העם הזה.** אהרן נדב ואביהוא ושבעים זקנים הנלוים עתה עמך:
@26 **ושפטו.** ודינין ית עמא: **יביאון.** מיתן: **ישפוטו הם.** כמו ישפוטו וכן (רות ב ח) לא תעבורי, כמו לא תעברי ותרגומו דינין אנון. מקראות העליונים הם לשון צווי, לכך מתרגמין וידונון ייתון, ידונון, ומקראות הללו לשון עשיה:
@27 **וילך לו אל ארצו.** לגיר בני משפחתו:
@28 **ביום הזה.** בראש חדש. לא היה צריך לכתוב אלא ביום ההוא, מהו ביום הזה, שיהיו דברי תורה חדשים עליך כאלו היום נתנו:
@29 **ויסעו מרפידים.** למה הצרך לחזור ולפרש מהיכן נסעו, והלא כבר כתב שברפידים היו חונים, בידוע שמשם נסעו, אלא להקיש נסיעתן מרפידים לביאתן למדבר סיני, מה ביאתן למדבר סיני בתשובה, אף נסיעתן מרפידים בתשובה: **ויחן שם ישראל.** כאיש אחד בלב אחד, אבל שאר כל החניות בתרעומת ובמחלוקת: **נגד ההר.** למזרחו, וכל מקום שאתה מוצא נגד, פנים למזרח:
@30 **ומשה עלה.** ביום השני. וכל עליותיו בהשכמה היו, שנאמר (שמות לד ד) וישכם משה בבקר: **כה תאמר.** בלשון הזה וכסדר הזה: **לבית יעקב.** אלו הנשים, תאמר להן בלשון רכה: **ותגיד לבני ישראל.** ענשין ודקדוקין פרש לזכרים. דברים הקשין כגידין:
@31 **אתם ראיתם.** לא מסרת היא בידכם, ולא בדברים אני משגר לכם, לא בעדים אני מעיד עליכם, אלא אתם ראיתם אשר עשיתי למצרים, על כמה עברות היו חיבין לי קדם שנזדוגו לכם, ולא נפרעתי מהם אלא על ידכם: **ואשא אתכם.** זה יום שבאו ישראל לרעמסס, שהיו ישראל מפזרין בכל ארץ גושן, ולשעה קלה כשבאו לסע ולצאת נקבצו כלם לרעמסס. ואונקלוס תרגם ואשא, ונטלית יתכון, כמו ואסיע אתכם, תקן את הדבר דרך כבוד למעלה: **על כנפי נשרים.** כנשר הנושא גוזליו על כנפיו, שכל שאר העופות נותנים את בניהם בין רגליהם, לפי שמתיראין מעוף אחר שפורח על גביהם, אבל הנשר הזה אינו מתירא אלא מן האדם, שמא יזרוק בו חץ, לפי שאין עוף אחר פורח על גביו, לכך נותנן על כנפיו, אומר מוטב יכנס החץ בי, ולא בבני. אף אני עשיתי כן, (שמות יד יט) ויסע מלאך האלהים וגו' (שם כ) ויבא בין מחנה מצרים וגו' , והיו מצרים זורקים חצים ואבני בליסטראות והענן מקבלם: **ואבא אתכם אלי.** כתרגומו:
@32 **ועתה.** אם עתה תקבלו עליכם יערב לכם מכאן ואלך, שכל התחלות קשות: **ושמרתם את בריתי.** שאכרות עמכם על שמירת התורה: **סגלה.** אוצר חביב, כמו (קהלת ב ח) וסגלת מלכים, כלי יקר ואבנים טובות שהמלכים גונזים אותם. כך אתם תהיו לי סגלה משאר אמות, ולא תאמרו אתם לבדכם שלי ואין לי אחרים עמכם, ומה יש לי עוד שתהא חבתכם נכרת: **כי לי כל הארץ.** והם בעיני ולפני לכלום:
@33 **ואתם תהיו לי ממלכת כהנים.** שרים כמה דאת אמר (שמואל ב' ח יח) ובני דוד כהנים היו: **אלה הדברים.** לא פחות ולא יותר:
@35 **וישב משה את דברי העם** וגו' **.** ביום המחרת, שהוא יום שלישי, שהרי בהשכמה עלה. וכי צריך היה משה להשיב, אלא בא הכתוב ללמדך דרך ארץ ממשה שלא אמר, הואיל ויודע מי ששלחני, איני צריך להשיב:
@36 **בעב הענן.** במעבה הענן וזהו ערפל: **וגם בך.** גם בנביאים הבאים אחריך: **ויגד משה.** ביום המחרת שהוא רביעי לחדש: **את דברי העם** וגו' **.** תשובה על דבר זה שמעתי מהם שרצונם לשמוע ממך אינו דומה השומע מפי השליח לשומע מפי המלך, רצוננו לראות את מלכנו:
@37 **ויאמר ה' אל משה.** אם כן, שמזקיקין לדבר עמם, לך אל העם: **וקדשתם.** וזמנתם, שיכינו עצמם היום ומחר:
@38 **והיו נכנים.** מבדלים מאשה: **ליום השלישי.** שהוא ששה בחדש. ובחמישי בנה משה את המזבח תחת ההר ושתים עשרה מצבה, כל הענין האמור בפרשת ואלה המשפטים, (שמות כד ד) ואין מקדם ומאחר בתורה: **לעיני כל העם.** מלמד שלא היה בהם סומא, שנתרפאו כלם:
@39 **והגבלת.** קבע להם תחומין לסימן, שלא יקרבו מן הגבול והלאה: **לאמר.** הגבול אומר להם, השמרו מעלות מכאן והלאה, ואתה תזהירם על כך: **ונגע בקצהו.** אפלו בקצהו:
@40 **ירה יירה.** מכאן לנסקלין שהם נדחין למטה מבית הסקילה, שהיה גבוה שתי קומות: **יירה.** ישלך למטה לארץ, כמו (שמות טו ד) ירה בים: **במשך היבל.** כשימשוך היובל קול ארוך הוא סימן סלוק שכינה והפסקת הקול, וכיון שנסתלק הם רשאין לעלות: **היבל.** הוא שופר של איל, שכן בערביא קורין לדכרא יובלא, ושופר של אילו של יצחק היה:
@41 **מן ההר אל העם.** מלמד שלא היה משה פונה לעסקיו אלא מן ההר אל העם:
@42 **היו נכנים לשלשת ימים.** לסוף שלשה ימים, הוא יום רביעי שהוסיף משה יום אחד מדעתו, כדברי רבי יוסי, ולדברי האומר בששה בחדש נתנו עשרת הדברות לא הוסיף משה כלום. לשלשת ימים, כמו (פסוק יא) ליום השלישי: **אל תגשו אל אשה.** כל שלשת ימים הללו כדי שיהו הנשים טובלות ליום השלישי ותהיינה טהורות לקבל תורה שאם ישמשו תוך שלשת ימים, שמא תפלוט האשה שכבת זרע לאחר טבילתה ותחזור ותטמא, אבל מששהתה שלושה ימים כבר הזרע מסריח ואינו ראוי להזריע וטהור מלטמא את הפולטת:
@43 **בהית הבקר.** מלמד שהקדים על ידם מה שאין דרך בשר ודם לעשות כן, שיהא הרב ממתין לתלמיד, וכן מצינו ביחזקאל (יחזקאל ג כב) קום צא אל הבקעה וגו' , (שם כג) ואקום ואצא אל הבקעה והנה שם כבוד ה' עומד:
@44 **לקראת האלהים.** מגיד שהשכינה יצאה לקראתם, כחתן היוצא לקראת כלה, וזהו שנאמר (דברים לג ב) ה' מסיני בא, ולא נאמר לסיני בא: **בתחתית ההר.** לפי פשוטו ברגלי ההר. ומדרשו שנתלש ההר ממקומו ונכפה עליהם כגיגית:
@45 **עשן כלו.** אין עשן זה שם דבר, שהרי נקוד השי''ן פת''ח, אלא לשון פעל, כמו אמר, שמר, שמע, לכך תרגומו תנן כליה, ולא תרגם תננא, וכל עשן שבמקרא נקודים קמ''ץ מפני שהם שם דבר: **הכבשן.** של סיד, יכול ככבשן זה ולא יותר, תלמוד לומר (דברים ד יא) בער באש עד לב השמים. ומה תלמוד לומר כבשן, לשבר את האזן, מה שהיא יכולה לשמוע, נותן לבריות סימן הנכר להם. כיוצא בו (הושע יא י) כאריה ישאג, וכי מי נתן כח בארי, אלא הוא, והכתוב מושלו כאריה, אלא אנו מכנין ומדמין אותו לבריותיו, כדי לשבר את האזן מה שיכולה לשמוע. וכיוצא בו (יחזקאל מג ב) וקולו כקול מים רבים, וכי מי נתן קול למים, אלא הוא, ואתה מכנה אותו לדמותו לבריותיו, כדי לשבר את האזן:
@46 **הולך וחזק מאד.** מנהג הדיוט, כל זמן שהוא מאריך לתקע קולו מחליש וכוהה, אבל כאן הולך וחזק מאד. ולמה כך, מתחלה לשבר אזניהם מה שיכולין לשמוע: **משה ידבר.** כשהיה משה מדבר ומשמיע הדברות לישראל שהרי לא שמעו מפי הגבורה אלא (שמות כ ב) אנכי ולא יהיה לך והקדוש ברוך הוא מסיעו לתת בו כח להיות קולו מגביר ונשמע: **יעננו בקול.** יעננו על דבר הקול, כמו (מלכים א' יח כד) אשר יענה באש, על דבר האש להורידו:
@47 **וירד ה' על הר סיני.** יכול ירד עליו ממש, תלמוד לומר (שמות כ יט) כי מן השמים דברתי עמכם. מלמד שהרכין שמים העליונים והתחתונים והציען על גבי ההר, כמצע על המטה, וירד כסא הכבוד עליהם:
@48 **העד בעם.** התרה בהם שלא לעלות בהר: **פן יהרסו** וגו' **.** שלא יהרסו את מצבם על ידי שתאותם אל ה' לראות ויקרבו לצד ההר: **ונפל ממנו רב.** כל מה שיפול מהם ואפלו הוא יחידי חשוב לפני רב: **יהרסו.** כל הריסה מפרדת אסיפת הבנין, אף הנפרדין ממצב אנשים הורסים את המצב:
@49 **וגם הכהנים.** אף הבכורות שהעבודה בהם: **הנגשים אל ה'.** להקריב קרבנות, אף הם אל יסמכו על חשיבותם לעלות: **יתקדשו.** יהיו מזמנים להתיצב על עמדם: **פן יפרץ.** לשון פרצה, יהרוג בהם ויעשה בהם פרצה:
@50 **לא יוכל העם.** איני צריך להעיד בהם שהרי מתרין ועומדין הם היום שלשת ימים, ולא יוכלו לעלות שאין להם רשות:
@51 **לך רד.** והעד בהם שנית, שמזרזין את האדם קדם מעשה, וחוזרין ומזרזין אותו בשעת מעשה: **ועלית אתה ואהרן עמך והכהנים.** יכול אף הם עמך, תלמוד לומר ועלית אתה. אמור מעתה, אתה מחצה לעצמך ואהרן מחצה לעצמו והם מחצה לעצמם. משה נגש יותר מאהרן, ואהרן יותר מן הכהנים, והעם כל עיקר אל יהרסו את מצבם לעלות אל ה': **פן יפרץ בם.** אף על פי שהוא נקוד חטף קמ''ץ אינו זז מגזרתו, כך דרך כל תבה שנקדתה מלאפו''ם כשהיא סמוכה במקף משתנה הנקוד לחטף קמ''ץ:
@52 **ויאמר אליהם.** התראה זו:
@53 **וידבר אלהים.** אין אלהים אלא דין. לפי שיש פרשיות בתורה שאם עשאן אדם מקבל שכר, ואם לאו אינו מקבל עליהם פרענות, יכול אף עשרת הדברות כן, תלמוד לומר וידבר אלהים, דיין לפרע: **את כל הדברים האלה.** מלמד שאמר הקדוש ברוך הוא עשרת הדברות בדבור אחד, מה שאי אפשר לאדם לומר כן. אם כן מה תלמוד לומר עוד אנכי ולא יהיה לך, שחזר ופרש על כל דבור ודבור בפני עצמו: **לאמר.** מלמד שהיו עונין על הן הן ועל לאו לאו:
@54 **אשר הוצאתיך מארץ מצרים.** כדאי היא ההוצאה שתהיו משעבדים לי. דבר אחר לפי שנגלה בים כגבור מלחמה, ונגלה כאן כזקן מלא רחמים, שנאמר (שמות כד י) ויראו את אלהי ישראל ותחת רגליו כמעשה לבנת הספיר, זו היתה לפניו בשעת השעבוד, (שם) וכעצם השמים, משנגאלו, הואיל ואני משתנה במראות אל תאמרו שתי רשויות הן, אנכי הוא אשר הוצאתיך ממצרים ועל הים. דבר אחר לפי שהיו שומעין קולות הרבה, שנאמר, (להלן פסוק טו) את הקולות, קולות באין מארבע רוחות ומן השמים ומן הארץ, אל תאמרו רשויות הרבה הן. ולמה אמר לשון יחיד, אלהיך, לתן פתחון פה למשה ללמד סנגוריא במעשה העגל, וזהו שאמר (שמות לב יא) למה ה' יחרה אפך בעמך, לא להם צוית, לא יהיה לכם אלהים אחרים, אלא לי לבדי: **מבית עבדים.** מבית פרעה שהייתם עבדים לו. או אינו אומר אלא מבית עבדים, שהיו עבדים לעבדים, תלמוד לומר (דברים ז ח) ויפדך מבית עבדים מיד פרעה מלך מצרים, אמור מעתה עבדים למלך היו, ולא עבדים לעבדים:
@55 **לא יהיה לך.** למה נאמר, לפי שנאמר (פסוק ד) לא תעשה לך, אין לי אלא שלא יעשה, העשוי כבר מנין שלא יקים, תלמוד לומר לא יהיה לך: **אלהים אחרים.** שאינן אלהות אלא אחרים עשאום אלהים עליהם, ולא יתכן לפרש אלהים אחרים זולתי, שגנאי הוא כלפי מעלה לקרותם אלהות אצלו. דבר אחר אלהים אחרים, שהם אחרים לעובדיהם, צועקים אליהם ואינן עונין אותם, ודומה כאלו הוא אחר שאינו מכירו מעולם: **על פני.** כל זמן שאני קים, שלא תאמר לא נצטוו על עבודה זרה אלא אותו הדור:
@56 **פסל.** על שם שנפסל: **וכל תמונה.** תמונת כל דבר אשר בשמים:
@57 **אל קנא.** מקנא לפרע ואינו עובר על מדתו למחול על עוון עבודה זרה, כל לשון קנא אינפרינמינ''ט בלעז , נותן לב לפרע: **לשנאי.** כתרגומו, כשאוחזין מעשה אבותיהם בידיהם:
@58 **ועשה חסד.** נוצר חסד שאדם עושה, לשלם שכר עד לאלפים דור, נמצאת מדה טובה יתרה על מדת פרענות אחת על חמש מאות, שזו לארבעה דורות וזו לאלפים:
@59 **לשוא.** (השני לשון שקר כתרגומו) כמא דתימר (שבועות כט א) אי זהו שבועת שוא, נשבע לשנות את הידוע, על עמוד של אבן שהוא של זהב. (הראשון לשון מגן, כתרגומו) זה הנשבע לחנם ולהבל, על של עץ עץ ועל אבן אבן:
@60 **זכור.** זכור ושמור בדבור אחד נאמרו. וכן (שמות לא יד) מחלליה מות יומת, (במדבר כח ט) וביום השבת שני כבשים, וכן (דברים כב יא) לא תלבש שעטנז, (שם יב) גדילים תעשה לך, וכן (ויקרא יח טז) ערות אשת אחיך, (דברים כה ה) יבמה יבא עליה, הוא שנאמר (תהלים סב יב) אחת דבר אלהים שתים זו שמעתי. זכור לשון פעול הוא, כמו (ישעיה כב יג) אכול ושתו, (שמואל ב ג טז) הלוך ובכה, וכן פתרונו תנו לב לזכור תמיד את יום השבת, שאם נזדמן לך חפץ יפה תהא מזמינו לשבת:
@61 **ועשית כל מלאכתך.** כשתבא שבת, יהא בעיניך כאלו מלאכתך עשויה, שלא תהרהר אחר מלאכה:
@62 **אתה ובנך ובתך.** אלו קטנים. או אינו אלא גדולים, אמרת הרי כבר מזהרים הם, אלא לא בא אלא להזהיר גדולים על שביתת הקטנים, וזו ששנינו (שבת קכא א) קטן שבא לכבות אין שומעין לו, מפני ששביתתו עליך:
@63 **וינח ביום השביעי.** כביכול הכתיב בעצמו מנוחה ללמד המנו קל וחמר לאדם, שמלאכתו בעמל וביגיעה, שיהא נח בשבת: **ברך ויקדשהו.** ברכו במן לכפלו בששי לחם משנה, וקדשו במן שלא היה יורד בו:
@64 **למען יאריכון ימיך.** אם תכבד יאריכון, ואם לאו יקצרון, שדברי תורה נוטריקון הם נדרשין מכלל הן לאו ומכלל לאו הן:
@65 **לא תנאף.** אין ניאוף אלא באשת איש, שנאמר (ויקרא כ י) מות יומת הנואף והנואפת, ואומר (יחזקאל טז לב) האשה המנאפת תחת אישה תקח את זרים: **לא תגנב.** בגונב נפשות הכתוב מדבר. לא תגנבו (ויקרא יט יא) בגונב ממון. או אינו אלא זה בגונב ממון, ולהלן בגונב נפשות, אמרת דבר הלמד מענינו, מה לא תרצח, לא תנאף, מדבר בדבר שחייבין עליהם מיתת בית דין, אף לא תגנוב דבר שחיב עליו מיתת בית דין:
@67 **וכל העם ראים.** מלמד שלא היה בהם אחד סומא. ומנין שלא היה בהם אלם, תלמוד לומר (שמות יט ח) ויענו כל העם. ומנין שלא היה בהם חרש, תלמוד לומר (שמות כד ז) נעשה ונשמע: **ראים את הקולות.** רואין את הנשמע, שאי אפשר לראות במקום אחר: **את הקולת.** (מכילתא בחדש פ''ט) היוצאין מפי הגבורה: **וינעו.** (שם) אין נוע אלא זיע: **ויעמדו מרחק.** היו נרתעין לאחוריהם שנים עשר מיל כאורך מחניהם ומלאכי השרת באין ומסיעין אותן להחזירם, שנאמר (תהלים סח יג) מלכי צבאות ידדון ידדון:
@69 **לבעבור נסות אתכם.** לגדל אתכם בעולם שיצא לכם שם באמות שהוא בכבודו נגלה עליכם: **נסות.** לשון הרמה וגדלה, כמו (ישעיה סב י) הרימו נס, ארים נסי (ישעיה מט כב) , וכנס על הגבעה (ישעיה ל, יז) , שהוא זקוף: **ובעבור תהיה יראתו.** על ידי שראיתם אותו יראוי ומאים, תדעו כי אין זולתו ותיראו מפניו:
@70 **נגש אל הערפל.** לפנים משלש מחיצות, חשך ענן וערפל שנאמר (דברים ד יא) וההר בוער באש עד לב השמים חשך ענן וערפל, ערפל הוא עב הענן, שנאמר לו (שמות יט ט) הנה אנכי בא אליך בעב הענן:
@71 **כה תאמר.** בלשון הזה: **אתם ראיתם.** יש הפרש בין מה שאדם רואה למה שאחרים משיחין לו, שמה שאחרים משיחין לו פעמים שלבו חלוק מלהאמין: **כי מן השמים דברתי.** וכתוב אחד אומר וירד ה' על הר סיני, בא הכתוב השלישי והכריע ביניהם (דברים ד לו) מן השמים השמיעך את קולו ליסרך ועל הארץ הראך את אשו הגדולה, כבודו בשמים ואשו וגבורתו על הארץ. דבר אחר הרכין שמים ושמי השמים והציען על ההר, וכן הוא אומר (תהלים יח י) ויט שמים וירד:
@72 **לא תעשון אתי.** לא תעשון דמות שמשי המשמשים לפני במרום: **אלהי כסף.** בא להזהיר על הכרובים, שאתה עושה לעמוד אתי, שלא יהיו של כסף, שאם שניתם לעשותם של כסף הרי הן לפני כאלהות: **ואלהי זהב.** בא להזהיר שלא יוסיף על שנים, שאם עשית ארבעה, הרי הן לפני כאלהי זהב: **לא תעשו לכם.** לא תאמר הריני עושה כרובים בבתי כנסיות ובבתי מדרשות כדרך שאני עושה בבית עולמים, לכך נאמר לא תעשו לכם:
@73 **מזבח אדמה.** מחבר באדמה, שלא יבננו על גבי עמודים או על גבי כפים. דבר אחר שהיה ממלא את חלל מזבח הנחשת אדמה בשעת חניתן: **תעשה לי.** שתהא תחלת עשייתו לשמי: **וזבחת עליו.** אצלו, כמו (במדבר ב כ) ועליו מטה מנשה. או אינו אלא עליו ממש, תלמוד לומר (דברים יב כז) הבשר והדם על מזבח ה' אלהיך, ואין שחיטה בראש המזבח: **את עלתיך ואת שלמיך.** אשר מצאנך ומבקרך. את צאנך ואת בקרך, פרוש לאת עולתיך ואת שלמיך: **בכל המקום אשר אזכיר את שמי.** אשר אתן לך רשות להזכיר שם המפרש שלי, שם אבא אליך וברכתיך אשרה שכינתי עליך מכאן אתה למד שלא נתן רשות להזכיר שם המפרש אלא במקום שהשכינה באה שם, וזהו בית הבחירה. שם נתן רשות לכהנים להזכיר שם המפרש בנשיאת כפים לברך את העם:
@74 **ואם מזבח אבנים.** רבי ישמעאל אומר כל אם ואם שבתורה רשות, חוץ משלשה ואם מזבח אבנים תעשה לי, הרי אם זה משמש בלשון כאשר, כאשר תעשה לי מזבח אבנים לא תבנה אתהן גזית שהרי חובה עליך לבנות מזבח אבנים, שנאמר (דברים כז ו) אבנים שלמות תבנה, וכן (שמות כב כד) אם כסף תלוה, חובה הוא, שנאמר (דברים טו ח) והעבט תעביטנו. ואף זה משמש בלשון כאשר וכן (ויקרא ב יד) ואם תקריב מנחת בכורים זו מנחת העמר, שהיא חובה, ועל כרחך אין אם הללו תלוין, אלא ודאין, ובלשון כאשר הם משמשים: **גזית.** לשון גזיזה שפוסלן ומסתתן בברזל: **כי חרבך הנפת עליה.** הרי כי זה משמש בלשון פן, שהוא דילמא, פן תניף חרבך עליה: **ותחללה.** הא למדת, שאם הנפת עליה ברזל חללת, שהמזבח נברא להאריך ימיו של אדם, והברזל נברא לקצר ימיו של אדם, אין זה בדין, שיונף המקצר על המאריך. ועוד, שהמזבח מטיל שלום בין ישראל לאביהם שבשמים, לפיכך לא יבא עליו כורת ומחבל. והרי דברים קל וחמר ומה אבנים שאינם רואות ולא שומעות ולא מדברות על ידי שמטילות שלום אמרה תורה לא תניף עליהם ברזל, המטיל שלום בין איש לאשתו, בין משפחה למשפחה, בין אדם לחברו, על אחת כמה וכמה שלא תבואהו פרענות:
@75 **ולא תעלה במעלות.** כשאתה בונה כבש למזבח, לא תעשהו מעלות מעלות אישיקלונ''ש בלעז [מדרגות] אלא חלק יהא ומשופע: **אשר לא תגלה ערותך.** שעל ידי המעלות אתה צריך להרחיב פסיעותיך, ואף על פי שאינו גלוי ערוה ממש, שהרי כתיב (שמות כח מב) ועשה להם מכנסי בד, מכל מקום הרחבת הפסיעות קרוב לגלוי ערוה הוא, ואתה נוהג בהם מנהג בזיון. והרי דברים קל וחומר ומה אבנים הללו שאין בהם דעת להקפיד על בזיונן אמרה תורה הואיל ויש בהם צורך, לא תנהג בהם מנהג בזיון, חברך שהוא בדמות יוצרך, ומקפיד על בזיונו, על אחת כמה וכמה:

@1 **וישמע וגו'**. צריך לדעת לאיזה ענין יחסו בייחוס כהן מדין שאין זו מעלה אלא ירידה ומן הראוי ראשונות לא תזכרנה. ואולי כי יכוון שבח האיש באומרו **כהן מדין** לומר שהגם שהיו לו ב' בחינות הרמוזות בכהן מדין שהם היותו ראש למדין ואדוק לעבודה זרה אף על פי כן עשה ב' דברים נגדיים והפכיים לב' הפרטים. כנגד היותו גדול אמר **חותן משה** שנתחתן לאדם שלא נודעה לו גדולה עדיין, ודבר זה יקפידו עליו נוהגי שררה ואין צריך לומר א' המיוחד לאומתו שיקפיד לתת בתו לאדם בלא שם, וכנגד היותו אדוק לעבודה זרה כמשמעות המובן מתיבת כהן אמר הכתוב (י''א) מה שאמר בסוף הענין עתה ידעתי כי גדול ה' מכל האלהים ודבר זה אין בו חידוש ומעלה גדולה באמור כן גוי א' לקובעו בתורה אלא באמצעות מה שקדם ליחסו בשם כהן מדין דבר גדול הוא שכהן אומה אחת מהם ובהם יעיד על כי הכל יפצה פיהם:
@1 **עוד** טעם אומרו **כהן מדין** לומר באמצעות כן השיג לדעת כל אשר עשה ה', כי לאנשים הגדולים יתגלה ויודע הכל בצדק בלא תוספת וגרעון מה שאין כן לשאינם רשות הגם שיודע להם החדשות לא ידעו כל הדברים הנעשים:
@1 **את** כל אשר וגו' גם זה יגיד שבח האיש שהשתדל לדעת כל פרטי המעשים, וזה יגיד כי אהב את יעקב, שהלא תראה איש שונא לרעהו יקוץ בהגדת שבחיו וטובו ויחדל מדעת מצבו הטוב, אשר לא כן אהוב לאהובו, ורשם ה' בדתו כי זה האיש אהב את ישראל. עוד ירצה בדקדוק עוד למה הוציא הכתוב פרט זה של הוצאת ישראל ממצרים מכלל כל אשר עשה. ועוד כי הוא עיקר כל אשר עשה ולא היה צריך לפרשה:
@1 **אכן** לצד כי יתרו מן הסתם ידע תוקף שבית מצרים כאמור בדבריהם (מכילתא) כי אסירי מצרים לא פתחו מעולם, ומה גם לדבריהם (סנהדרין קו. שמו''ר פ''א) שאמרו כי יתרו היה מיועצי פרעה ובקי במצרים ואסיריה, ולזה הגם שישמע כי הוציא וגו' לא יצדיק היציאה בלבו, לזה הקדים הכתוב דבר שממנו הצדיק כי הוציא ואמר **וישמע יתרו את כל אשר עשה** פירוש כל הנפלאות והנוראות אשר עשה ה' בהצדקת נביא, והוא אומרו **אשר עשה למשה** והנפלאות שעשה להצלת ישראל בין ברדיית מחזיק בם בין בהפלאתם מהמכות בין בנס הים וכו' ובזה ידע **כי הוציא** וגו', ולזה לא אמר וכי הוציא וזולת שמיעת כל הנעשה מהפלאים לא היה מצדיק הגם שישמע ששלחם כי לא יאמין ואם יאמין לא יבטח כי יאמר שוב ירדפו אחריהם ואם רדפו ולא יכלו יכינו עוד מחנה וירדפו:
@1 **אכן** במה ששמע **כל אשר** וגו' הצדיק כי הוציא. ותמצא כי רבותינו ז''ל נחלקו (זבחים קט''ז.) באיזה מהשמועות נרגש מהם אמרו קריעת ים סוף ומהם אמרו מלחמת עמלק, וזה מתאים לדברינו. ולדברי האומר מלחמת עמלק ממה שסמך לו וישמע, זה יגיד כי לא הספיק לו כל מה ששמע מהנפלאות כי יתלה שהסובב הוא פחזותו של פרעה שהתרים כנגד שלוחו של מקום לא לצורך הצלת ישראל כי לא היה ה' טורח כל כך בשבילם וכפי זה אין בטחון לישראל מעמים אשר יקומו עליהם לזה אמר הכתוב ששמע מלחמת עמלק, וכבר הפליאו רבותינו ז''ל (מכילתא) לומר מה עצמה המלחמה הארורה. ונראה לפרש לדרך זה אומרו כי הוציא פירוש לצד ששמע כל אשר עשה ובכלל זה מלחמת עמלק בזה הצדיק כי כל המופתים לא היו אלא למעלה ולחיבת ישראל להוציאם ובשבילם עשה כל אשר עשה ושמיעת עמלק יגיד:
@1 **עוד** ירצה באומרו **כי הוציא** לסמוך אחריה הגדת קיחת יתרו את צפורה וגו' על דרך אומרם ז''ל (שמו''ר פ''ד) כי אמר יתרו למשה למה אתה מוליך אשתך וכו' אמר לו עתידין ישראל לקבל התורה על הר סיני ולא יהיו בני בכלל אמר לו לך לשלום וכו' עד כאן, ולזה אמר הכתוב **כי הוציא ויקח** וגו' לקיים דברו:
@2 **ויקח יתרו חותן משה**. פירוש לצד שהיה חותן משה מצא עשות ככה שהלך להר האלהים וגו' שהניחוהו מיראתו של משה כי נפלה אימתו על כל העמים, אבל זולת זה היו מונעין אותו מלכת לכפור באמונתם ומה גם שחשוד היה בעיניהם, ותמצא שכל אומה תחייב מיתה לכופר באמונתם, ולצד היות יתרו לחותן משה היא שעמדה לו, ואולי שירמוז עוד כי הגם שהיה ליתרו כינוי של גדולה ליקרות כהן מדין מאם בכינוי זה ולקח לו כינוי חותן משה, והוא אומרו **ויקח יתרו** ומה לקח מהב' יחוסין שיחסו הכתוב בתחלה, **חותן משה** לא כהן מדין:
@2 **אחר שלוחיה** טעם שהוצרך לומר אחר שלוחיה, גם דקדק לומר לשון שלוחין, וזולת דברי רבותינו ז''ל (שמות רבה שם) שכתבתי בפסוק את כל אשר עשה וגו' נראה לומר כי משה גרשה כשראה שהיה עוסק במצות שליחותו יתברך לא ידע שיעור הזמן ושלחה מביתו, והבנים אליעזר קטן היה וצריך לאמו שנולד בדרך במלון, וגרשם מן הסתם קטן היה סמוך לאליעזר מלפניו, או לדבריהם ז''ל שאמרו (מכילתא) שהתנה עם יתרו בן אחד לבת ובן ב' לאב, לטעם זה נמצאו שניהם בידה, וכוונת הודעת ה' הדבר כאן לומר שבח יתרו ומעלת משה בעיניו שהגם ששלחה לקחה וטרח בכבודו ובעצמו להוליכה לו אפילו אחר שלוחיה, אלא לדבריהם ז''ל (שמו''ר) שאמרו שלא שלחה אלא סמך על הבטחת יתרו כי ידיו תביאנה, נראה לומר כי טעם אומרו **אחר שלוחיה** פירוש שלא היה הדבר אלא עד שקדמה ושלחה לו למשה שלוחים וידעה מקום תחנותו והסכים על ידה אז הוא שלקח יתרו וגו' ויבא אל המדבר וגו':
@3 **שם האחד גרשום וגו'**. הוצרך לכתוב טעם השם פעם ב' אחר שכתבו בפרשת שמות (לעיל ב' כ''ב) כדי שתדע כי הוא זה האמור בפרשת שמות ולא אחר שנקרא על שמו:
@3 **עוד** אולי כי חש הכתוב שיאמר האומר כי טעם שקרא לו שם גרשום הוא לצד שגרשו יתרו מעל שלחנו או מביתו, והגם שאמר הטעם גר הייתי וגו', אולי כי לצד שלא ירגיש יתרו אמר כן, לזה חזר הכתוב והצדיק הדברים אפילו בזמן שלא יחוש להרגשת יתרו כי טעם **שם** וגו' **כי אמר** וגו'. ופירוש משמעות כי אמר גר וגו' פירשתיו בפרשת שמות (שם):
@4 **ושם האחד אליעזר וגו'**. טעם אומרו **האחד**, כי לצד טעם קריאת השמות טעמו של זה קדם לטעמו של שם גרשם שבתחלה הצילו מחרב פרעה ואחר בא למדין וגר שם, וטעם שלא הקדים קריאת שם אליעזר הוא כי קרא למאורע שהיה בו אז בארץ נכריה ואחר כך הלך לחפש מאורעות קודמות, או לפי מה שפירשנו בפסוק גר הייתי (שם) שיכוין על גרותו בעולם הזה בחינה זו קדמה להצלתו מחרב פרעה ולזה הקדימו, ולצד בחינת גרות ב' בארץ נכריה קדם לו כוונה הרמוזה בקריאת שם אליעזר וכנגד זה אמר האחד ולזה הוצדך לפרש מה הוא העזר שכנגדו קרא לו שם ואמר **ויצילני** וגו', ובזה יוצדק לומר עליו שם **האחד**, וזולת אומרו ויצילני מחרב פרעה הייתי מפרש שהעזר הוא אחר הגרות והקדימה שהקדים לומר גר הייתי וגו' תחייבני לפרש כן ויסתם בפני ידיעת טעם אומרו האחד:
@5 **אל המדבר וגו'**. פירוש ואם תאמר מנין ידעו מקום תחנותו במדבר הגדול, לזה אמר **אשר הוא חונה שם** וגו' פירוש וכבר הודיעו משה מקום אשר דבר אתו שם האלהים ואמר אליו (לעיל ג' י''ב) תעבדון את האלהים על ההר הזה והודיעו ההר שעליו יקבלו התורה, והוא אומרו אשר הוא חונה שם הר וגו' הידוע אצלו. ותמצא שאמרו ז''ל (שמו''ר פ''ד) שאמר משה ליתרו ענין קבלת התורה וכתבתיו בתחלת הפרשה ותהיה הודעת הר האלהים מכלל מה שהודיעו:
@6 **אני חותנך וגו' ואשתך וגו'**. טעם ששינה הכתוב סדרם כאן מסדר שכתב בפסוק שלפני זה שהקדים הבנים לאשה, יתבאר על פי דבריהם ז''ל (מכילתא, שמו''ר כאן) שאמרו אם אין אתה יוצא בגיני וכו', אם כן ממטה למעלה סדרם הכתוב, לזה הקדים האשה לבנים שאם לא יעשה בשבילה יעשה בשביל הבנים, מה שאין כן כשהודיע הכתוב ביאתם למדבר וסדרם סדר החשוב חשוב קודם הקדים הבנים, והגם שהקדים שם יתרו לבנים וכאן סדרו קודם לאשה שיורה שהוא למטה ממנה, הוא יתרו דבר בענוה ושפלות אבל הכתוב כבדו והקדימו לצד היותו חותנו של משה וצריך לכבדו אפילו משה דכתיב (ש''א כ''ד) ואבי ראה גם ראה:
@6 **ושני** בניה עמה. טעם אומרו **עמה**, נתכוון לומר חלוקה רביעית שאם אין אתה עושה בגינה לבד ולא בגין בניה לבד צרף כבוד שניהם וצא:
@7 **ויצא וגו' לקראת חותנו**. פירוש לצד שאמר לו יתרו אם אין אתה יוצא בגיני וכו' לזה אמר הכתוב **ויצא משה לקראת חותנו** כי כבודו של חותנו הספיק לו לצאת לקראתו. ואולי שעשה היכר לדבר שיצא ביחוד לקראתו ולא פנה ביציאתו למקום אהל האשה וילדיה, או שהיה אומר בפירוש שיציאתו הוא לקראת חותנו, גם לדבריהם ז''ל (מכילתא) שמשה הוא שהשתחוה ליתרו זה לך האות כי לכבודו יצא, ולזה אמרו ז''ל (שם) כבוד גדול נתכבד יתרו וכו', וזולת דברינו מנין לו כבוד מיציאה זו דלמא לכבוד בניו ואשתו יצא משה:
@7 **וישתחו וגו'**. רבותינו ז''ל (שם) אמרו איני יודע מי השתחוה למי כשהוא אומר איש מי הוא שקרוי איש זה משה עד כאן. הנה טעם שלא אמרו כי שניהם השתחוו זה לזה לצד שאמר לשון יחיד וישתחו וישק לו זה יגיד כי אחד לבד השתחוה. ואם תאמר לדבריהם ז''ל והלא מצינו שגם יתרו נקרא איש דכתיב (לעיל ב' כ''א) ויואל משה לשבת את האיש, יש לחלק בין קריאת איש של יתרו לקריאת איש של משה, וקודם אעירה שחר מה מעלה יש בשם זה של איש והלא כל אדם יקרא איש ונקבתו אשה, וגם בבהמות מצינו שאמר הכתוב בפרשת נח (בראשית ז') שבעה איש ואשתו, אלא שישתנה שם איש כשיהיה במקום זכרון האדם ויוסף לו ליווי קריאת איש זה יגיד שהוא לשון מעלה לבמקום שיאמר איש בלא זכרון שמו זה ימצא במקום השם ולא יגיד מעלה, כמו שתאמר (בראשית כד כא) והאיש משתאה לה, וימצאהו איש (בראשית לז טו), וגם זכרון אנשים שאמרו ז''ל (במד''ר פט''ז) שהוא לשון חשיבות דוקא בצירוף זכרון שמם דכתיב (במדבר יג ג) כולם אנשים שאחר שזכר שמם חזר לומר כולם אנשים זה יגיד לשון חשיבות, מה שאין כן כשיהיה במקום הזכרת שמם כנוי זה אין זו מעלה כאומרו (במדבר כ''ב ט') מי האנשים האלה עמך והנה מצינו שאמר הכתוב (לעיל י''א) גם האיש משה, כי זה משה האיש (לקמן ל''ב) הרי הזכיר שמו והוסיף לומר האיש זה יגיד כי למעלה ואדנות יכוין, וזה הוא אומרם מי הוא שקרוי איש זה משה פירוש איש לשון שררות וממשלות, אבל יתרו הגם שמצינו לו שנקרא איש לא מצינו אותו בליווי אלא במקום זכרון שמו אמר האיש והוא שם הצודק על כל נברא זכר, ומעתה כשאמר הכתוב כאן **איש** הדבר שקול אם הוא כנוי הרגיל בבחינת הזכרים או פירושו הוא איש הרשום למעלה וחשיבות, ותיבה זו מונחת בין יתרו ובין משה אם נאמר שפירושו הוא כנוי לזכר יכנם במשמעות גם יתרו ושניהם שקולים במשמעות ואין אני יכול לעשות שניהם שהרי הכתוב לא אמר אלא אחד כמו שדייקנו מאומרו וישתחו, ואחד זה אין אני יודע מי הוא ולא בא הכתוב לסתום אלא לפרש, ובהכרח לומר כי פירוש **איש** האמור כאן הוא לשון חשיבות ובאומרו כן נתחייב לומר כי זה הוא משה האיש שאליו נתייחד חשיבות זה ולא ליתרו ובזה לא סתם הכתוב כוונתו והרי פירש שעל משה הוא אומר:
@8 **ויספר משה**. הגם שאמר הכתוב וישמע וגו' את כל אשר וגו' אולי שהיו פרטים שלא שמעתן אזנו. או אפשר שלא הצדיק הפלאות לצד הגזמת העניינים, או שהגם שקדם לו מהידיעות עדיין היה מסתפק שלא נרתק חבל מצרי שעל צואריהם, וספר לו משה ענין שלא היה יכול לדעת מזולתו והוא הריגת שר מצרים שאמרו רבותינו ז''ל (זהר ח''ב נ''ב:) שראהו ישראל מת ובזה החליט יתרו כי פקע נירם מעליהם, ואולי כי זה הוא שרמז הכתוב באומרו **את כל התלאה אשר מצאתם בדרך ויצילם** וגו' שהודיעו מרדיפת השר כי יתרו כהן מדין היה ומן הסתם הם יבחינו וידעו כי יש שרי מעלה על כל אומה וספר לו כי רדף אותם הוא בעצמו דכתיב (לעיל י''ד י') והנה מצרים נוסע אחריהם ומזה רעשו ופחדו ישראל וכמו שפירשנו שם, וכששמע יתרו כן אמר **ברוך** וגו' **מתחת יד מצרים** שהוא השר שמצרים שמו ונכון:
@9 **ויחד יתרו**. תרגום אונקלום וחדי. וצריך לדעת למה ידבר הכתוב כאן ארמית ולא אמר לשון ברור שהוא לשון הקודש. והגם שאמרו ז''ל (סוטה ל''ב.) בשבעים לשון, אף על פי כן דבר יגיד בשנותו את טעמו. ונראה כי יודיע הכתוב כי מרוב השמחה נתחדד בשרו, כי תמצא כשתהיה לאדם שמחה והוא דבר שלא כפי המשוער במושג הרגיל תולד בו הרגשה בהרכבת מזגו ולפעמים יתעלף ולפעמים יסתכן ממש, ועיין מה שפירשתי בויגש בפסוק (בראשית מ''ה כ''ו) לאמר עוד יוסף חי. והנה יתרו הגם שקדם אצלו ידיעה מבשורות הטובות אף על פי כן כששמע תוכן הנס ומה גם ברדיפת המלאך אותם כמו שפירשתי בפסוק (ח') ויספר משה והצילם ה' נתחדד בשרו, ודבר זה מורגש הוא אצל כל בעל חי מרגיש:
@11 **עתה ידעתי וגו'**. פירוש כי הגם שיש לאומות שרים גדולים ועצומים להלחם בעדם ולהרע לאויביהם וכל מרים יד כנגדם אף על פי כן לא יכוונו להנקם מהאומות הנגדיית בדמיון המרד מה שאין כן אלהי ישראל שיכוין למדוד במדה עצמה של המורד ועושה רשעה שקע שוקעיהם וכו', גם יש לתלות במאורע הרע כי לא מצד שכנגדו הוכה מה שאין כן אלהי ישראל שכל המכות והיסורין אשר יסר פרעה הם מכוונים למה שזדו עליהם. וצא ולמד מה שאמרו ז''ל (תנחומא) בכוון המכות שכל אחת כנגד מדה אחת רעה שזדו המצריים וכו':
@12 **ויקח יתרו וגו' עולה וגו'**. הנה נתחכם יתרו לזבוח שלמים רבים, וזה היה לו לאות כי מזמין הוא גדולי ישראל על שולחנו, ולזה לא אמר הכתוב ויקרא לאהרן ולזקני ישראל לאכל וגו' אלא **ויבא אהרן** וגו' פירוש מעצמן באו כי מעשיו מוכיחים ההזמנה כדי שלא יבואו קדשים לידי נותר וכבדוהו ובאו מעצמן אהרן והזקנים ולא הטריחוהו להזמינם על הזבח:
@15 **כי יבא אלי העם וגו'**. קשה מה תשובה זו עושה והלא ראה יתרו כי בא אליו העם לדרוש וכוונת קושיתו הוא למה יתנהג במנהג זה כי יש טורח לעם. ודבריו ברור מללו אתה יושב לבדך פירוש ואין שופטים אחרים לדון העם, ולו יהיה שלא הבין משה דבריו, היה לו לשאול גזירת הדיבור לא שיאמר לו דברים שעליהם הוא מקשה. ונראה כי משה הבין בדברי יתרו במה שאמר **אשר אתה עושה** וגו' משמע כי משה מכריחם ומחייבם שלא לעמוד לפני דיין זולתו וזה סיבה שסובלים העם הטורח ואם יחפוץ ימנה עליהם דיינים וילכו לדון לפניהם, לזה השיבו כי לא ממנו אלא מהעם כי יבא מעצמו אלי ולא לזולתי חפץ ללכת, ולצד שיקשה לך למה יחפצו בטורח זה, הטעם הוא **כי יהיה להם דבר בא אלי** ואמרו ז''ל (זהר ח''ב ע''ח.) בא אלי הדבר עצמו ויצטדק הדין לאמתו, ודבר זה לא ימצא בזולתי:
@15 **ומעתה** אין מציאות למנות דיינים וילכו העם לפניהם, וגמר אומר **והודעתי** וגו' פירוש גם דבר זה אי אפשר בזולתי. ויתרו נסתפק במשמעות דברי משה שסובל ב' דרכים. הא' כי לצד שבאים אצלו העם הוא חש על המצוה לדון בין איש וגו' לעשותה הוא ולא אחרים, והב' כי העם לא יחפצו לזולתו לצד מה שפירשנו בדבריו, לזה השיבו כנגד המובן מדבריו כי יבחר עשות המצוה בעצמו ולא ימנע עשות טוב אמר **לא טוב הדבר אשר אתה** וגו' כאשר יבאר הטעם. וכנגד מה שמובן מדבריו כי העם לא יתרצו ללכת לזולתו אמר **איעצך** וגו' **היה אתה לעם** וגו' **ואתה תחזה** וגו' **ושפטו את העם בכל עת** פירוש בכל דין שיהיה המשפט רצוי לב' בעלי דינים ומן הסתם כשידונו להם משפט רצוי למה יבחרו בטורח הגדול, **והיה** וגו' פירוש וכשיהיה דבר גדול של התעצמות הדין בין לצד השופטים שלא יוכלו השג בין לצד הנשפטים שלא יתרצו ב' הכתות במשפטם יביאו אליך, ולא לצד פרט זה תתחייב בכל:
@18 **נבל תבל**. כפל לומר **נבול** וגו', להיות כי יש ב' גדרים במשמעות **תבול**, הא' כל שיגרע כל שהוא מכחו הראשון יקרא עליו הלאות לערך הקודם אבל על כל פנים יכול עשות מה שהיה עושה קודם במעט יגיעה. והב' הוא הלאות הנרגש לכל שהוא גדר המונע האדם מעשות חפצו לצד כי לא ישאר בו כח, לזה אמר אליו כי מה שיגיע אליו מהלאות כח לא שיעור מועט אלא שיעור שכפי האמת יקרא לו **תבול**, והוא מה שגמר אומר **לא תוכל עשוהו לבדך**. או אולי שכפל כנגד מה שאמר גם אתה גם וגו':
@18 **גם אתה גם העם הזה**. טעם אומרו **גם** בחלוקה ראשונה ושניה, ירצה לא מבעיא זולתך במצב זה אלא **גם אתה** כי רב חילך, ואומרו **גם העם הזה** פירוש ישראל לצד שצריכין להמתין זה לזה בדין כמעשה האמור בענין ויעמוד וגו' ואומרו תיבת **גם** לצד שטרחם אינו מקובץ ביחיד. ורבותינו ז''ל (מכילתא) אמרו גם זה אהרן העם אלו הע' זקנים, וצריך לדעת טעם רבותינו ז''ל שפירשו כן, ואם לצד גם היה להם לפרש כמו שפירשנו. אכן לצד שראו כי בעצתו אמר שימנה סך גדול מישראל שרי אלפים וגו' שעולה בהם למנין שמונה רבבות גילה דעתו כי לא יספיקו ע' זקנים. ולדבריהם ז''ל יתפרש אומרו **גם** מלבד הזקנים, **וגם** שנית פירוש מלבד משה, ויש רבותא בכל אחד, משה לצד מעלתו, והזקנים לצד היותם רבים, או אפשר שנתכוון באומרו **גם אתה** לרבות העם שיגיע להם הלאות אנשים כשיהיו ממתינים זה לזה בדין, ואומרו גם ב' לרבות הגם שיצטרף הוא עם הזקנים:
@21 **ואתה תחזה**. פירוש לא שהעם ימנו עליהם אלא הוא יחזה. עוד רמז כי לצד זה יחשב כאלו הוא השופט כיון שהם שלוחיו ויטול חלק במצות:
@21 **מכל העם**. פירוש הגם שימצא בני אדם שיראה בעיניו כי הם ראויים לדבר, אף על פי כן לא יהיה מתרצה בהם עד שיבקש כל העם ויקח הגדול שבכולם בכל בחינה מבחינות הטובות המנויות בדבריו:
@21 **אנשי חיל וגו'**. אמר ד' הדרגות כנגד ד' מינוים המוזכרות בדבריו, כנגד שרי אלפים אמר **אנשי חיל**, תיבת חיל תגיד עוצם השלמת האושר והמדות והגבורה וכללות השלימות, כי כן צריך להיות שר האלף, וכנגד שרי המאות אמר **יראי אלהים** כי לצד פרט זה לא יצטרך כל כך אלא כשיהיה ירא אלהים ראוי להתמנות שר למאה, ודקדק לומר **יראי אלהים** שצריכין להיות יראים יראת העונש, כי יש לך לדעת כי הירא בבחינת שם הוי''ה לצד שיהיה בדעתו כי ה' רחום וחנון לפעמים יחטא ויסמוך על רחמיו כי יאריך אפו וכדומה אבל יראת העונש תרעיד המשכיל, וכמו שתמצא שכל גדולי עולם יראים מדקדוקי המשפט הגם כי יודעים שמעשיהם ישרים ונכונים, וצא ולמד ממאמר חכמינו ז''ל (חגיגה ד') שאמרו במעשה בעלת אוב כשעלה שמואל והביא עמו משה רבינו ע''ה יעויין שם דבריהם, ואשר על כן אמר יראי אלהים כי צריכין להיות בגדר יראה מדקדוקי המשפט באין רחמים, ובחינה זו ישנה גם כן בשרי האלפים אלא שנוסף בהם פרטים אחרים שאין צורך להם בשר המאה, וכנגד שרי חמשים אמר **אנשי אמת** שיספיק לגדר זה הגם שלא השיגו לבחינה זו של יראת עוצם הדין אלא שיהיו אנשי אמת שישתדלו על העמדת האמת לבל תהיה נעדרת, וכנגד שרי עשרות אמר **שונאי בצע** די להם גדר זה ובזה יהיו ראוים להיות שרי עשרות, ודקדק לומר **שונאי** פירוש כי יהיה להם הדבר שנאוי לא שיצטרכו להרחיק תאותם כי לאלה יש חשד שינוצחו מהרשע המפתה וכל מדות הג' ישנם באנשי חיל, וכל מדות הב' ישנם ביראי אלהים, ומדת שונאי בצע ישנה באנשי אמת והם זו למעלה מזו, ולזה לא אמר ויראי וגו' ואנשי אמת ושונאי בצע אם כולם יתקבצו יחד באדם א' היה צריך לומר וא''ו בכל אחת או לפחות בחלוקה האחרונה אלא ודאי כמו שכתבתי שאין צורך לזה בכל הפרטים. והנה פשיטא שאם ימצא ממין המשובח שבכולן לכל המנויים מה טוב ומה נעים, ולזה כשבקש משה בישראל מצא ממין המשובח אנשי חיל שיעור שיספיק לכולם כאומרו ויבחר משה אנשי חיל מכל ישראל ולא הוצרך לפרט שאר הפרטים כי ישנם בבחינת אנשי חיל, וזה יצדיק לך גם כן פירושינו בדברי יתרו, שאם כוונתו לומר זאת ועוד אם כן היה לו למשה לבחור גם כן כל הרמוזים בדברי יתרו, ואין לומר חם ושלום כי לא מצא בישראל יראי אלהים אנשי אמת וגו' אלא ודאי כדברינו שלא הזכיר יתרו שאר הפרטים אלא לצד שחש יתרו שלא ימצא שיעור המספיק מבחינה הגדולה והיה מסתפק במדרגה קטנה כנזכר:
@21 **וראיתי** לתת לב איך זכה יתרו שתכתב על ידו פרשה זו, והן אמת כי הוא כבד משה עבד ה' והנה שכרו שכבדו ה', אלא היה ה' יכול עשות לו דרך כבוד אחר לא בדרך זה שיראה חס ושלום כפחות ידיעה בעם ה' עד שבא כהן מדין והשכילם:
@21 **ונראה** כי טעם הדבר הוא להראות ה' את בני ישראל הדור ההוא וכל דור ודור כי יש באומות גדולים בהבנה ובהשכלה, וצא ולמד מהשכלת יתרו בעצתו ואופן סדר בני אדם אשר בחר כי יש באומות מכירים דברים המאושרים, והכונה בזה כי לא באה הבחירה בישראל לצד שיש בהם השכלה והכרה יותר מכל האומות, וזה לך האות השכלת יתרו הא למדת כי לא מרוב חכמת ישראל והשכלתם בחר ה' בהם אלא לחסד עליון ולאהבת האבות. ויותר יערב לחיך טעם זה למאן דאמר (זבחים קט''ז.) יתרו קודם מתן תורה בא כי נתחכם ה' על זה קודם מתן תורה לומר שהגם שיש באומות יותר חכמים מישראל אף על פי כן אותנו הביא ה' אליו ובחר בנו, ועל זה בפרט עלינו לשבח לאשר בחר בנו מצד חסדיו. גם למאן דאמר אחר מתן תורה יש טעם במה שסדר ביאתו קודם להראות הכוונה הנזכרת שזולת זה אין הכונה הנזכרת נגלית והבן:
@22 **בכל עת**. רמז אפילו בזמן שהוא משה עסוק בקבלת חוקי ה' ותורותיו וכדומה אלו הם פנויים ישפוטו בכל עת מה שאין כן יכול עשות משה:
@22 **והקל מעליך ונשאו**. פירוש כי מה שאני אומר לך להקל מעליך לא שלא תשפוט אלא הדבר הגדול אלא **ונשאו אתך** פירוש אתה והם תהיו במלאכה זו:
@23 **אם את הדבר וגו' וצוך וגו'**. צריך לדעת כוונת אומרו **וצוך**, אם להמלך בגבורה הוא אומר כבר אמר לו כן פעם אחת דכתיב (פסוק י''ט) איעצך ויהי אלהים עמך, ומה צורך בכפל הדברים. ואולי שנתכוון לומר לו תשובה על מה שיטעון כי סוף כל סוף הוא מונע מעצמו המצות ואין ממדת הצדיקים להקל מעליהם המצות הגם כי ייעף וכי יגע כי אדם לעמל יולד (איוב ה') בעמלה של מצוה, לזה אמר אליו **וצוך אלהים** וגו' פירוש כי הנה ידוע הוא עוצם הכח אשר יצטרך לאיש נביא, וצא ולמד ממאמרי דניאל (דניאל י') בדבר אליו מלאך ומזה תשכיל לדברות אל, ולזה תמצא שאמרו ז''ל (נדרים ל''ח.) אין נבואה שורה אלא על גבור, והן אמת כי משה זיכך גופו ולא יארע לו התשות כח, אבל על כל פנים לא יכול להתאזר כל כך כשיהיה חלש בטבעו. ולזה אמר אליו כי יותר במצוה זו שיכולה להתקיים על ידי אחרים כדי שיקיים מצות הנבואה שאינה יכולה להתקיים על ידי זולתו, והוא אומרו **אם את** וגו' **וצוך אלהים** פירוש כאשר יצוך אלהים המצות אשר הוא מצוך בהודעת התורה והמצוה תוכל עמוד בהם פירוש יהיה בך כח לעמוד בהם. ואולי כי דקדק לומר לשון עמידה לומר כי יהיה בו כח לקבל הנבואה מעומד כאומרם ז''ל (זהר ח''א קע''א.) כי שאר הנביאים היו נופלים על פניהם מה שאין כן משה דכתיב ונצבת שם וגו' (שמות לד ב) פה עמוד עמדי (דברים ה כח), ולזה אם לא יקל מעליו זה יהיה לו סיבה שיגרע מצדיק עינו חס ושלום ולא יוכל עמוד:
@28 **בחדש השלישי וגו'**. הנה למה שקדם מעוצם חיבתו יתברך בישראל וגודל חשקו לתת להם ארוסתם זאת התורה תקשה למה נתעכב ה' מתת התורה עד חודש השלישי כי מן סימני האהבה היא שלא יתעכב חושק מבא לחשוקתו. ואם לצד הדרך הלא מצינו שאפילו לאליעזר עבד אברהם קפצה לו הארץ (סנהדרין צ''ה.) בלכתו לקחת אשה ליצחק ומכל שכן וקל וחומר לחתונת נשיאת ראש כי תקפוץ הארץ וגם השמים אם יצטרכו לה, אשר על כן בא הקדוש ברוך הוא ונתן אמתלא לדבר כי לא מיעוט החשק הוא הסובב אלא לצד הכשרת החתן כי לא היו ישראל ראוים לצד שהיו בארץ הטמאה והיו לנדה ביניהם והוצרכו לספור ספירת טהרתם שבע שבתות כדרך ז' נקיים אשר צוה ה' לזבה (זהר ח''ג צ''ז:) והוא אומרו **לצאת בני ישראל** פירוש לסיבת יציאתם מארץ מצרים הוא הסובב עכבת הדבר עד החודש הג', והראיה כי כשקרבו ימי הכשרתם בו ביום נסעו בו ביום באו, והוא אומרו **ביום הזה** פירוש שנסעו בו ביום באו, וכן הובא בדבריהם ז''ל (שבת פ''ז:) שביום שנסעו בו באו. והצצתי בענין ואראה עוצם חשקו יתברך בישראל שניכרת מתוך מעשיו בהעיר למה הטריחם ה' בדרך עד החדש הג'. ואם לסיבה שכתבנו עדיין תקשה שהיה לו לקפוץ הארץ ולהגיע למדבר סיני בו ביום ושם יתעכבו עד ספור ז' שבועות ויהיה זמן הכושר כנזכר:
@28 **אכן** זה יגיד עוצם חשק נתינת התורה לישראל, כי לגודל חשקו ברוך הוא בהם לא רצה להביאם ולהתעכב זמן ארוך בלא חתונה בבית חתנות, ולזה היה ממעיט הימים בריחוק מקום, ותקח לך שיעורן של דברים מחשוק וחשוקתו כי לא יצטער בעכבתו מבוא אליה כל זמן שלא הגיעו עת דודים ועדיין לא עלתה כלה לחופתה אשר לא כן בעת כלה בחופתה לא יעצור כח לעכב ביאתו אליה:
@29 **ויסעו מרפידים**. קשה למה איחר המוקדם כי פסוק זה היה לו להקדים קודם פסוק שלפניו שאמר באו מדבר סיני, ואולי שהוא על דרך אומרם (סנהדרין ק''ה:) אהבה מקלקלת השורה להקדים המאוחר, שלהיות כי הוא זה יום המקווה לבורא לתורה לעולם לעליונים ולתחתונים ומיום הבריאה והם יושבים ומצפים מתי יבואו בני ישראל מדבר סיני, לזה כשהגיעו שמה לא עצרו כח לספר סדר הדבר ותכף קדמה ההודעה באומרו **ביום הזה באו** וגו' הגיע חשוק ונחשק לחושק וחשוק ושמחו שמים וארץ כי זה הוא תכלית הבריאה ותקותה ואחר כך חזר הכתוב להודיע פרטן של דברים:
@29 **עוד** ירצה בהעיר עוד אומרו **ויבואו מדבר סיני** והלא כבר אמר בכתוב שלפניו באו מדבר סיני. עוד צריך לדעת למה הוצרך לומר ויחנו במדבר הלא מובן הוא הדבר כי במקום ביאתם חנו:
@29 **אכן** כוונת הכתוב הוא להקדים ג' ענינים הם עקרי ההכנה לקבלת התורה שבאמצעותם נתרצה ה' להנחילם נחלת שדי היא תורתנו הנעימה:
@29 **הא'** הוא התגברות והתעצמות בעסק התורה כי העצלות הוא עשב המפסיד השגתה, ולזה תמצא כי כל מקום שיזכירנה ה' לתורה ידקדק לומר לשון חוזק ואומץ עד גדר שימית עצמו עליה דכתיב (במדבר יט יד) זאת התורה אדם כי ימות וגו' ודרשו ז''ל (שבת פ''ג:) וכו', כמו כן רבותינו ז''ל ידקדקו בהזכרתה לומר עסק התורה השתדלות התורה ורבים כמוהו, ועיין מה שפירשתי בספרי חפץ ה' שחברתי על קצת ממסכתות הש''ס בקטנותי במאמר רבותינו ז''ל (שם פ''ח:) למיימינים בה כו' ותראה כי לא תושג ההשגה אלא בהתעצמות גדול, וכנגד זו אמר הכתוב **ויסעו מרפידים**, לא בא להודיע מקום שממנו נסעו שאם כן היה לו להקדימו קודם תחנותם, אלא נתכוין לומר שנסעו מבחינת רפיון ידים כמו שמצינו שדרשו כן רבותינו ז''ל (סנהדרין ק''ו.) בפסוק (לעיל י''ז ח') וילחם עם ישראל ברפידים ברפיון ידים עד כאן. והן עתה נסעו מבחינה זו והכינו עצמם לעבוד עבודת משא בנועם ה', והוא אומרו **ויבואו מדבר סיני**:
@29 **וענין** ב' הוא השפלות והענוה כי אין דברי תורה מתקיימין אלא במי שמשפיל עצמו ומשים עצמו כמדבר, וכנגד זה אמר **ויחנו במדבר** פירוש לשון שפלות וענוה כמדבר שהכל דורכים עליו:
@29 **וענין** ג' הוא בחינת ייעוד חכמים בהתחברות בלב שלם ותמים לא שיהיו בד בבד שעליהם אמר הכתוב (ידמיה נ) חרב אל הבדים (בדכות ס''ג.), אלא יתועדו יחד ויחדדו זה לזה ויסבירו פנים זה לזה, וכנגד זה אמר **ויחן שם ישראל** לשון יחיד שנעשו כולן יחד כאיש אחד, והן עתה הם ראוים לקבלת התורה:
@30 **ומשה עלה וגו'**. צריך לדעת למה עלה משה קודם שיקרא לו ה'. עוד צריך לדעת לאיזה מקום עלה, אם להר היה לו לומר אל ההר בפירוש. ורבותינו ז''ל אמרו (שמות רבה פכ''ח) זה הוא שאמר הכתוב (תהלים סח) עלית למרום וגו'. ולדבריהם קשה עוד כי מצינו שאחר כך היתה הקריאה אליו מן ההר דכתיב ויקרא וגו' מן ההר ואם הוא כבר עלה לשמים מה מקום לקריאה ממקום נמוך למקום עליון. עוד יש לדקדק למה אמר הכתוב **אל האלהים** ולא אמר אל ה' כמו שגמר אומר ויקרא אליו ה' וגו':
@30 **אכן** כוונת הכתוב היא להיות שקדם ה' ואמר למשה בסנה (לעיל ג' י''ב) בהוציאך את העם תעבדון את האלהים על ההר הזה, הוא מראהו כי שם הוא מקום קבלת התורה, אשר על כן בהגיעו שמה עשה משה משפט עבד נאמן וקדם ועלה אל ההר ולא הוצרך להזכיר ההר כיון שהזכירו בסמוך דכתיב נגד ההר ועליו חוזר אומרו **ומשה עלה**, ואומרו **אל האלהים** הוא טעם עליתו כי מה שייכות בעליה זו לזה אמר אל האלהים שקדם אצלו מהבורא תעבדון את האלהים על ההר הזה לזה אם היה מתעכב עד שיקרא ה' אליו יראה התרשלות ומיעוט חשק בדבר לזה תיכף קדם והכין עצמו ועלה, וזולת מה שקדם לו במאמר ה' תעבדון את האלהים לא היה עולה אל ההר. ובזה נתיישבו כל הדקדוקים שדקדקנו. ואין בפירוש זה סתירה לדברי רבותינו ז''ל שאמרו (שמו''ר שם) עלית למרום כי בעלייתו ההר שהוא מקום שהרכין ה' שמים עליו הנה הוא נמצא עולה לשמים:
@30 **ויקרא אליו ה'**. פירוש כשקדם הוא ועלה תכף קרא לו ה'. ויש לך לדעת כי בחינת הקדושה לא תקדים אלא למזמין אותה ומעיר על הדבר והוא מאמרם ז''ל (זהר ח''ג צ''ב) באתערותא דלתתא אתערותא דלעילא, והוא סוד אומרו (בראשית ב ו) ואד יעלה מן הארץ והשקה מלמעלה את כל פני האדמה, וירמוז באומרו **ויקרא** לשון יקר וגדולה עשה ה' למשה על הכנתו וזריזותו בדבר:
@30 **מן ההר לאמר**. פירוש לצד כי דבר ה' בא מן שמי השמים כי עדיין לא ירד ה' על הר סיני, אשר על כן בא להודיענו הכתוב כי צוה ה' על הקול שיעבור דרך הר ומשם ישמע משה אמריו ולא יפנה לצדדין גם לא ישמע לאוזן משה קודם שיגיע להר אלא להר יבא ומן ההר יהיה נשמע אליו. וזה הוא שיעור הכתוב **ויקרא אליו ה'** ממקום ששמו שם כידוע וקריאה זו **מן ההר לאמר** פירוש מן ההר התחיל האמירה ולא קודם ולא מן הצדדים, ואם לא אמר הכתוב תיבת לאמר היה בנשמע כי התחלת הקריאה היה מן ההר וכבר ירדה שכינה שמה ולא כן הוא:
@30 **כה תאמר וגו' אתם ראיתם וגו'**. צריך לדעת למה כפל **תאמר** וגו' **ותגיד** וגו'. ורבותינו ז''ל אמרו (שמות רבה פכ''ח) בית יעקב הם הנשים ולהם יאמר מענה רך ולבני ישראל דברים קשים כגידים. וקשה הלא לא מצינו שאמר ה' בדבריו ב' מיני שליחות אלא לשון א' לכולם יחד אנשים ונשים אם הם קשים יחד ישמעוהו ואם הם רכים יחד ישמעוהו. ואין לומר שכשידבר משה ישנה מענה לשון מסדר הנדבר חס ושלום כי הלא תמצא כי בסוף דברי ה' אמר אליו (פסוק ו') אלה הדברים אשר תדבר אל בני ישראל ואמרו ז''ל (מכילתא) וזה לשונם לא פחות ולא יותר. ולכשנאמר כי כוונת אומרו **אל בני ישראל** הוא על האנשים, יחסר דרך אשר ידבר בו לנשים, גם אין אני רואה דברים קשים בדברי ה' לאנשים אלא דברים המחיים את הנפש:
@30 **אכן** כוונת דברי ה' הוא על זה הדרך וקודם אקדים המושג אצלינו מכל התורה כי האדון אלהי ישראל מדותיו הם להטיב ויותר מחשק המקבל חשקו להטיב, וזה לגודל הפלגת בחינת טובו, ויותר מהמה לבני ישראל, ומתחכם הוא יתברך להרבות שכרנו וטובתנו כי זה הוא אשר יחפוץ ה'. והנה מצינו לו שגילה דעתו כי שכר המקיים תורת ה' ומצותיו מיראה הוא מחצה מהעושה מאהבה מב' כתובים הבאים בהודעת שכר המצות באחד אמר (דברים ז ט) לאלף דור ובאחד אמר (לקמן כ' ו') לאלפים ודקדק בשר האלף שהוא השומר מיראה ושר האלפים שהוא לעושה מאהבה. והנה יש בבחינת האהבה צד גורם רעה כי לא תספיק לבעליה להשמר בתמידות לבל עבור איזה פעם באקראי כי יאמר שמצד קורבתו לבורא וחביבותו לא יקפיד עליו על זה כמנהג וסדר הרגיל בין הנבראים, ולהשכילך בענין ממשה אתה למד כי לצד רוב קורבתו וחיבתו עם ה' שגג ודבר אליו (לעיל ד' י''ג) שלח נא ביד תשלח, למה הרעתה וגו' (ה' כ''ב), לא הצלת וגו', וזה היה סיבה גודל קריבתו לפני ה' נתקררה היראה כי פשיטא שאדם אחר כשלא יהיה קרב כל כך תפול עליו אימתה ופחד. והנה האדון ה' צבאות לא כן יחשוב כמו שאמר הכתוב (דברים י' י''ז) אשר לא ישא פנים ולא וגו' ויקפיד אדרבה ביותר על אהובו ליסרו בתוספת מרובה על עוברו אפילו פעם אחת ואפילו על הקלה שבקלים כאומרו (תהלים נ') וסביביו נשערה מאוד ואמרו ז''ל (ב''ק נ'.) שמדקדק עם חסידיו כחוט השערה, ואשר על כן בעת נתינת התורה חשב ה' מחשבות טובות להועיל בקבלת התורה ולפניו ב' דרכים, א' לדבר דברי אהבה וחיבה ויש בזה תכלית דבר טוב כשיקבלוה מאהבה שקל הקודש כפול הוא בשכרם, ויש בזה צד אחר כי העושה מאהבה לפעמים לא ידקדק בפרט אחד מהתורה כדרך האב עם בנו המגעגעו והמשעשעו כיון שאין עליו בחינת המורא מה שאין כן כשתהיה קבלת התורה מחמת יראה מדרך הירא לפחד על דקדוק אחד כעבד מרבו ונמצא תמיד עומד לשמור עץ החיים וכן הוא בדבריהם ז''ל. (ירושלמי ברכות). ודרך ב' הוא לדבר דברים קשים כמלך שגוזר על עבדו בזריקת מרה ואימת מלכות, ויש בזה תכלית טוב שלא יזלזלו באחת מכל מצות התורה ואפילו באקראי ועראי אלא שמגיעם מחצית שכר משכר המגיעם בעשותם מאהבה:
@30 **אשר** על כן נתחכם ה' לצוות בב' אופנים בדרך אהבה ודרך שררה והפחדה ואמר גם שניהם במתק לשון צדיק בנושא אחד, והוא מה שהתחיל לומר **כה תאמר** על זה הדרך כה פירוש כסדר זה שאני אומר לך **תאמר לבית יעקב ותגיד** וגו' פירוש יש בו אמירה רכה שהיא דרך אהבה וחיבה **ותגיד** פירוש יש בו גם כן דברים קשים כגידים שהוא דרך הפחדה ויראה. ודקדק לומר **בית יעקב** באמירה **ובני ישראל** בקושי, לומר חלק החסר לכל אחד משניהם על זה הדרך כי בית יעקב הם מדריגה הקטנה שבאומתנו הקדושה אשר לא ישיגו עבוד ה' מאהבה אלא מיראה לזה המצוה להם שצריכין להוסיף עבוד מאהבה הרמוזה באמירה רכה כנזכר, ולבני ישראל שהם מדרגה הנבחרת והמעולה אשר ישיגו בחינת האהבה אמר כנגדם **ותגיד** שלא יספיק להם בחינת האהבה לגבי פרט אחד וצריכין הם ליראה ולאהבה מטעם שכתבנו, נמצאת אומר כי טובים השנים וצורך בהם לקיום התורה וצריך כל איש מישראל לקנות שניהם אהבה ויראה ושניהם יחד אמרם אל עליון בנעימות דבריו באומרו אתם ראיתם אשר עשיתי וגו' כאשר אבאר בסמוך בעזרת השם ודברי רבותינו ז''ל שאמרו (מכילתא) אלו הנשים ואלו האנשים הם דרך דרש:
@31 **אתם ראיתם וגו'**. צריך לדעת כוונת אל עליון במה. שדקדק לומר **אשר עשיתי למצרים** שיותר היה לו לומר אשר הוצאתי אתכם מארץ מצרים שהוא עיקר הדבר להתחייב להשתעבד ולחבק אמריו על כל אשר גמלם ה'. ואם להזכיר נפלאותיו הרי הם רשומים באומרו אשר הוצאתי מארץ מצרים וידוע הוא כי לא הוציאם אלא באמצעות המסות הגדולות:
@31 **והנה** לפי מה שפירשנו כי יכוין ה' לב' דברים שהם בחינת האהבה ובחינת היראה לזה רשם ה' שניהם במאמר. זה, היראה באומרו **אשר עשיתי למצרים** פירוש אשר יסרתי יסורי נקמה לממאן עשות מאמרי כמה מכות רעות באין מספר על אשר מאן עשות מצותי לשלוח אתכם, והיה הדבר הזה לכם לאות לעובר על מצותי כי אתנקם ממנו ביסורי נקמה וצרות רבות כאשר ראיתם וקחו מוסר, ונתכוין ה' לרמוז להם שהם בגדר זה עצמו של המצרים אם ימאנו לשמוע אל התורה ואל המצות וזו בחינת היראה יראת העונש, גם יש בנשמע מאמר **אשר עשיתי** יראת הרוממות בכל הנפלאות והאותות והמופתים אשר עשה למצרים. גם בזה הראה בחינת האהבה והחיבה שכל זה עשה בשבילנו הרעיש כל הבריאה ואבד אומה אחת בשבילנו, ולצד זה יתלהב אדם בחיבת הבורא אשר הפליא חסדו להם, והנה היא בחינת האהבה לה' אלהינו, והם ב' דברים הרמוזים באומרו **תאמר לבית יעקב** שלא תספיק היראה וצריך גם האהבה **ותגיד לבני ישראל** שלא תספיק בחינת האהבה וצריך גם היראה והטעם כמו שכתבנו:
@31 **ואשא אתכם**. הנה האריך האדון בבחינת האהבה כי הוא העיקר במצוה להרויח כפל השכר, וצריך התעצמות גדול להשיגה, לזה אמר ראו חיבתי בכם כרחם אב על בנים חביבין שאפילו מדרך כף רגליכם חסתי עליו ונשאתי אתכם על כנפי נשרים פירוש ענני כבוד היו ממוצעים תחתם, וכן הוא אומר (דברים ח ד) ורגלך לא בצקה, ועוד יש לאלוה מילין לעורר האהבה מה שאין כן היראה שבנקל תכנס בלב האדם לזה הספיק לו ברמיזתו במאמר אשר עשיתי למצרים כמו שפירשתי:
@31 **ואבא אתכם אלי**. ירצה כי לא קדם הקרבתם אל ה' כמשפט כל הקרב הקרב למשכן ה' שיקדים הוא לעורר חבתו כידוע שאין אלהי עולם מקדים לקרב עד שיעורר המתקרב את האהבה, וכן הוא מהמוסר כי ההדיוטות והקלים הם המשתדלים להתקרב לגדולים ונכבדים מהם ומכל שכן עם עבד מושלים, ואף על פי כן אמר ה' כי לא כן עשה אלא הגם שהיו גוי מקרב גוי ערום ועריה בלא שום התעוררות אף על פי כן אני הבאתי אתכם אלי ולא אתם התקרבתם אלי:
@31 **עוד** ירצה לומר שאחר שהוציאם ממצרים היו חוזרים מאחרי השכינה כמו שמצינו להם שהמרו אמרי אל בים סוף במן ובשליו וכדומה אף על פי כן היה ה' מושכם אליו בכל עת שהיו חוזרים לאחוריהם ומביאן ומקרבן אליו יתברך:
@31 **עוד** ירצה על דרך אומרם ז''ל (הגדה) אלו לא הוציא הקדוש ברוך הוא את אבותינו ממצרים מיד כו', והטעם כדי שלא ישתקעו בבחינת הרע בטומאת מצרים ולא תהיה חס ושלום עוד תקומה לשונאיהם של ישראל לזה מיהר להוציאם כדי שיעמדו במקום קדוש, והוא אומרו **ואביא אתכם אלי** דייק תיבת אלי לשלול השתקעות בחלק הרע רחמנא ליצלן והבן:
@31 **עוד** ירצה לשלול טענת הטוען כי הלא מצינו לו (ספרי ברכה) שהלך לשעיר ופארן לישמעאל ועשו והזמינם לקבל תורה ולא קבלו לטעם שאמרו ואם כן מה מעלה זו שמרומם לעם ישראל, לזה אמר **ואבא** וגו' פירוש על דרך אומרם ז''ל (ילקוט הראובני ר''פ בלק) בפסוק (במדבר כג ד) ויקר אלהים אל בלעם וגו' משל למלך שבא אוהבו לדבר עמו וכו' עד כאן, פירוש כי אתם הבאתי אתכם אלי מה שאין כן הם ששלחתי להם למקומם לשעיר ולפארן ואין זה אלא לדחותם לעתיד לבא ולחייבם בדין מה שאין כן אתם כי דעתי ורצוני לקרבכם אלי ואין לדמות מעשה ישראל למעשה אדום וישמעאל:
@32 **ועתה אם וגו'**. אומרו **ועתה**, על דרך אומרם ז''ל (ב''ר פכ''א) אין ועתה אלא תשובה, כי לצד שהיו ישראל מלוכלכים בחרמי העונות אשר קדמו להם וגם החדשים מקרוב באו בהמראתם ככתוב בתורה כמה פרטי חטאים במן בשליו בשבת במים וכאשר רצה אל עליון לתת התורה זכה וברה יסוד הקדושה והטהרה ורוחניות הרוחניות צוה להם שיחזרו בתשובה אפילו מחטא קל, וכבר קדם לנו מאמרם ז''ל (קידושין מ''ט:) בדין המקדש את האשה על מנת שהוא צדיק גמור ונמצא רשע שקידושיו קידושין כי חיישינן שמא עשה תשובה ובאמצעות תשובתו יקרא צדיק. עוד יתבאר בסמוך:
@32 **אם שמוע תשמעו וגו'**. צריך לדקדק טעם כפל **שמוע תשמעו**, ואולי יכוין ה' לצוותם על קבלת ב' תורות אחת אשר ישמיעם באותו מצב, ואחת היא תורה שבעל פה ודקדוקי סופרים וספרים וגדרי חכמים ותקנותם וגזירתם אשר יורו כרמוז במצות (דברים יז יא) לא תסור מכל הדבר אשר יגידו לך ימין ושמאל, ולזה אמר כנגד מה שמשמיעם מהמצות אז אמר **אם שמוע**, וכנגד תורות העתידים מפי חכמי ישראל אמר **תשמעו** לעתיד. ולדרך זה ידוייק על נכון אומרו **ועתה אם שמוע**, כי להיות שמצוה באומרו **תשמעו** על העתיד לזה סמך **ועתה אם שמוע** לומר אם שמוע עתה ותשמעו לעתיד כנזכר. ודקדק לומר בק **ולי**, על דרך אומרם ז''ל (במד''ר פי''ד) שומע מפי חכם וכו' כשומע מפי הגבורה, והוא אומרו כי מצוה זו שאני אומר לכם שתקבלו תקנת חכם צריך שתהיה לכם שוה כאלו אם השמעתיה והגדתיה לכם. ואולי כי בזה יתיישב מאמרם ז''ל (במס' שבת פ''ח.) שדרשו בפסוק (יז) ויתיצבו בתחתית ההר שכפה עליהם ההר כגיגית ואמר להם אם אתם מקבלים וכו' ואם לאו שם תהא קבורתכם, וקשה והלא הם אמרו (לקמן כ''ד ז') כל אשר דבר ה' נעשה ונשמע ומה מקום לכפייה זו, והתוס' תרצו שם שמא היו חוזרים כשיראו האש הגדולה שיצתה נשמתן עד כאן, ואין דבריהם נראים כי אדרבא יוסיפו פחד ופחת ויראו יראת הרוממות. ולפי מה שפירשתי כי ה' אמר להם ב' תורות אחת מפיו אז ואחת לעתיד מפי חכמים כנזכר נוכל לפרש תשובתם שאמרו כל אשר דבר ה' נעשה ונשמע שכוונתם היא על זה האופן כל אשר דבר ה' חלק ממנו שהוא מה שאמר **ועתה אם שמוע** שהוא ענין הנאמר מפי הגבורה אז נעשה אנו מקבלין עלינו לעשות מעתה קודם שנשמעהו, וחלק ממנו שהוא מה שאמר **תשמעו** לעתיד שהוא תורת חכם ונשמע פירוש לא קבלו ולא מאנו אלא תלו הדבר עד שישמעו לדעת מה יעשה ישראל, כי הם דברים שאין להם שיעור ואין גבול לקבלה זו כי בכל דור ודור יחדשו דינים וגדרים וסייגים ותקנות ומי יכלכל תורה שאין לה שיעור כזו, לזה תלו שיהיה הדבר ברשותם עד שישמעו ויבחנו בכל דבר אם יוכלו קבל, ומעתה לא קבלו עליהם אלא תורה שבכתב אבל תורה שבעל פה הדבר תלוי ועומד, ועל זה כפה ה' עליהם ההר כגיגית עד שקבלו עליהם תורת חכם, ובאונס היה עד ימי מרדכי שראו פעולת חכם לחיים אשר עשו להם מרדכי ואסתר חזרו לקבל ברצון לקיים כל דבר אשר יחדשו ויתקנו עליהם חכמיהם אחר אשר ראו מה גדלו מעשה הצדיקים שזולתם לא היה נשאר רושם משונאיהם של ישראל. והגם שרבותינו ז''ל (שם) דרשו אומרם נעשה ונשמע באופן אחר לשבח שדמו למלאכים שקדמו לומר המעשה קודם השמיעה כמלאכים שמקדימין (תהלים קג) עושי דברו קודם לשמוע בקול דברו, זה דרך דרש. וגם לדרכנו הרי אמרו נעשה קודם שישמעו ולא הקדימו השמיעה אלא בתורת חכם. או אפשר שהכתוב נתכוון לב' הפירושים אחד בצדיקים ואחד בשאר העם כי פשיטא שמן הסתם לא ישוו הדרגות ישראל יחד בצדקות:
@32 **עוד** ירמוז בכפל **שמוע תשמעו** מה שהיה אחר האמת בקבלת התורה על פי דבריהם ז''ל (הוריות ח'.) כי ב' דברות שמעום מפי הגבורה וח' מפי המלאך שנברא מדיבורו יתברך לזה אמר **אם שמוע תשמעו** ב' הדרגות השמיעה, ודקדק לומר כנגד שמיעה שישמעו ממש מהגבורה **תשמעו בקולי** ולא אמר לקולי והבן:
@32 **עוד** ירצה לומר כי אם יתחיל לשמוע התורה משם ואילך הוא יתאוה לשמוע עוד, והוא אומרו **אם שמוע** עתה אני מבטיחכם כי תשמעו מעצמכם כשתטעמו טעמה, כאומרו (תהלים לד) טעמו וראו כי טוב ה'. עוד ירצה על דרך אומרם ז''ל (סוטה כ''א:) תורה בין וכו' מגנא ומצלא, והוא אומרו **אם שמוע** פירוש אם תהיה השמיעה זה יהיה לכם לב' תועליות הא' שאתם שומעים קולו יתברך דברי אלהים שיש בהם החיים ותחיו כאומרו (ישעי' נה) שמעו ותחי נפשכם, והב' **ושמרתם את בריתי** פירוש שיגן עליכם מיצר הרע, ולדרך זה הרווחנו גזירת הדבור שמקומו הוא תשמעו וגו' שעיקר המצוה הוא שמיעת התורה וממנה נמשכים כל התועליות, הא' שהם נהנים מקול אלהים חיים, ב' יהיו שומרים המצות ולא ישלוט בהם יצר הרע, ג' והייתם לי סגולה וגו'. ולפי מה שפירשתי למעלה כי אומרו תשמעו הוא לתורה שבעל פה, תהיה גזרת הכתוב **ושמרתם** וגו' כי באמצעות התורה תצילהו מיצר הרע המחטיאו, ואומרו בתוספת וא''ו, לומר מלבד שתהיה לכם ידיעה ממנה להבחין בין טוב לרע עוד לכם שתשיגו השמירה ולא ישלוט בכם השטן:
@32 **עוד** יכוין הכתוב על זה הדרך **ועתה אם שמוע** פירוש תכינו עצמיכם לשמוע אני אשמיעכם את קולי פירוש שלא אדבר עמכם על ידי שליח, גם רמז כי באמצעות שישמעו הדברים ממנו יתברך משמיעה אחת ישמעו עוד שמיעות רבות, על דרך אומרו (תהלים סח) ה' יתן אומר המבשרות צבא רב ותדלה נפשם מים חיים חכמה ותבונה, וזה שיעור הכתוב **אם שמוע** פירוש שמיעה שממנה תשמעו עוד שמיעות רבות היא שמיעה בקולי, והוא אומרו **תשמעו בקולי**, עוד יש לכם תועלת בזה **ושמרתם את בריתי** על דרך אומרם ז''ל (שהש''ר פ''א בפסוק ישקני) כי השומע תורה מפי אדם היא עומדת לישכח ממנו מה שאין כן השומע מפי עליון שמורה לעד ולעולמים, והוא אומרו ושמרתם את בריתי. גם ירצה על דרך אומרם ז''ל (שבת קמ''ו.) ישראל שעמדו על הר סיני פסקה זוהמתן, והכוונה היא כי באמצעות דבור ה' להם בכח בגדי מלכות שנתן להם שהיא נפש אדם ובאמצעות כן תתרצה הנפש למאוס בגעולי גוים המתאוים הרע, והוא אומרו **ושמרתם את בריתי**:
@32 **והייתם לי וגו'**. הכוונה בזה היא כי כשם שהסגולה הוא דבר שאינו כפי הטבע כי הלא תמצא כי יש עשב שטבעו קר וסגולתו לרפאות חולי הקרירות, וכן יש עשב חם וכו', וזה אינו כפי הטבע אלא דבר סגולה, וכמו כן מבטיחם ה' שיהיו סגולה גם שלא כפי המשוער, ויש הרבה ענפים בהבטחה זו, ראשונה על דרך אומרם ז''ל (שבת ס''ג) חשב אדם מישראל לעשות מצוה ונאנס ולא עשאה נותנים לו שכר כאלו עשאה, ולא כן בעבירה, ובאומות אינו כן אלא להיפך, ואין זה מהנשער כפי השכל ממה נפשך אם המחשבה תעשה דבר אם כן תעשה בחושב רע ואם לא תעשה אלא בבחינת הטוב ולא בבחינת הרע אם כן באומות למה בהפך. עוד תמצא (סנהדרין נ''ט.) כותי שעוסק בתורה או ששבת חייב מיתה, ואפילו שאר מצות אין לו לעשות, ולמה אם הפעולה מצד עצמה פעולה טובה כל העושה הרי זה עושה דבר טוב, לזה אמר הכתוב **והייתם לי סגולה מכל העמים** כי אין פעולה טובה יוצאה אלא מידכם שאין סגולת התורה והמצות אלא מכם. ואומרו **כי לי כל הארץ**, פירוש כי יאמר האומר כי הבטחה זו שיהיו סגולה לא תוצדק אלא כשיהיו האומות חפצים ללמוד ולעשות וגו' בזה יוצדק לומר שעשנו סגולה, אבל רואני (ספרי ברכה) כי אדרבה מאנו העמים לקבל תורה ומצות כשדבר ה' לפארן ושעיר ומעתה במה יוכר טוביות הבטחת המעלה, לזה אמר **כי לי כל הארץ**, כאן הודיע ה' כי אין לך אומה ואומה שאין בה מכירי אלהותו יתברך, וכן הוא אומר (מלאכי א') מוקטר מוגש לשמי וגו' הרי כי כל הגוים לו יכרעו ואף על פי כן לא יטלו שכר על הדבר ולא יעשה מעשיהם רושם, וזו היא סגולתם של ישראל:
@32 **עוד** ירצה שיהיו סגולה והסגולה היא שיהיו מיוחדים לו ביחוד לעבוד אלהי עולם מכל העמים כי גם כל העמים לי הם פירוש עבודתם לי הוא כי אינם עובדים אלא למשרתיו הא כיצד עובדים לשמש ולירח ולצבא השמים הלא כולם משמשיו יתברך ונמצאים עובדים לעבדיו כאומרו (דברים ד') אשר חלק ה' וגו' לכל העמים:
@32 **ומה** שמצינו שמרד פרעה וסנחריב וכו' הוא בדרך טעות ושגיון, הא למה הדבר דומה למלך שנחבא ויצא לפני שאינם מכירים אותו הרי הוא כהדיוט ולפעמים עבדיו עצמם יזלזלו בו כפחות הפחותים כמו כן פרעה לא ידע כי הוא זה האדון השליט על מי שחושב שהוא אלוהו, נמצאת אומר כי כל הארץ למשרתי מלכותו ישתחוו ובחר לו לישראל שיעבדוהו לו ביחוד ועשאם סגולה:
@32 **והצצתי** בהשכלת דבר זה שאמרו ז''ל בספרי בפרשת וזאת הברכה וזה לשונם כשנגלה ה' על ישראל לתת התורה הלך אצל בני עשו אמר להם מקבלים אתם התורה אמרו לו מה כתוב בה ואמר להם לא תרצח אמרו לפניו רבונו של עולם כל עצמו של אותו אביהם רוצח היה ועל כך הבטיחו אביו ועל חרבך תחיה הלך אצל עמון ומואב וכו' אמרו לו מה כתוב בה לא תנאף וגו' אמרו לו כל עצמה של ערוה להם היא הלך ומצא בני ישמעאל אמר להם וכו' לא תגנוב וכו' רבונו של עולם כל עצמו של אביהם לסטים היה וכו' עד כאן. הנה מאמר זה תמוה הוא כי מה יצדק אנוש עם אל ומה טענה פחותה זו וכי בשביל שאביהם רשע היא טענה הנשמעת, ועוד מי שאכל שום וריחו וכו', ותגדל הקושיא איך קבל ה' את טענתם כנשמע שיש בה ממש:
@32 **אכן** אשכילך כי כל אשר עיניך תחזינה בתורתינו בין במצות עשה בין במצות לא תעשה טעם הדברים הוא כי ה' בחן במה שברא והכיר בחינת הרע והבדילנו ממנו ובחן בחינת הטוב וקדשנו בו, והוא מאמר הזוהר (תקו''ז תיקון כ''א) בפסוק ועשה לי מטעמים כאשר אהבתי ממצות עשה ולא כאשר שנאתי ממצות לא תעשה, וכן הוא מאמר רבותינו ז''ל בספרא (מכילתא פס' כי אני ה' רופאך) אמר ה' למשה אמור להם לישראל דברי תורה שאני נותן לכם רפואה הם לכם חיים הם לכם עד כאן, כפל לומר רפואה וחיים כנגד מצות לא תעשה ומצות עשה, רפואה לבל תחלו באכלכם או בעשותכם מהמעשים הרעים, וחיים הם בעשותכם מעשים אשר יעשה אותם האדם וחי בהם, ותמצא כי בעת צוות ה' על דברים האסורים יאמר (ויקרא יא מג) אל תשקצו את נפשותיכם, אל תטמאו וגו' (ויקרא יח כד), גם יזכיר העריות בשם תועבה וכדומה לזה, להגיד בא האלהים כי כל מחשבותיו הם לשמור אותנו להיות בבחינת הקדושה וצונו להיות קדושים. ויש לך לדעת כי כל בחינת מעשה הרע יש לה שורש בבחינת רוח הטומאה, וכל בחינת מעשה הטוב היא בחינת שורש הקדושה והטהרה, והנה כל מצוה שצונו ה' עליה לבל עשותה שמה הוא שם בחינת הרע שממנו הוא, כמו שתאמר שיקוץ הניאוף שורש בחינת הרע כך שמו, הגזל כמו כן כך שם שורש בחינת הרע, ובעת עשות האדם מפעל הרע הנה הוא מחזיק שורשו הרע, ובעת שיהיה נזהר מעשותו הנה הוא ביטולו, וכמו שפירשו במאמרם ז''ל (מדרש תהלים פצ''ב) בפסוק הנה אויביך ה' וגו'. ודע כי מעשה האדם יגיד על שורש נפשו אם שורש ראש ולענה שהוא בחינת הרע או אם שורש המתוק והערב שהוא בחינת הקדושה, וכבר כתבתי ענף מזה בפרשת ויחי בפסוק ראובן בכורי וגו'. ובזה מצאנו מאור הברייתא שבאנו עליה. כי טענה נצחת טענו ג' הכתות עשו ישמעאל עמון ומואב כל אחד למה שנגע לו, עשו אמר כי שורש נפשותם הוא מבחינת הרע ההוא ששמו רציחה ממנו הוא כמעשהו ובעת קבלתם הדבר זה הוא שלילת הוייתם, וכמו כן עמון ומואב וישמעאל, וזה הוא שדקדק כל אחד ואמר כל עצמו של אביהם וכו' פירוש כל הווייתו הוא בנוי מבחינת הרע ששמה רוצח, וכמו כן אמרו מואב וכו' עצמה של ערוה פירוש שאתה מצוה עליה להם היא פירוש הם בחינתה ואיך יקבלו ההפכיות אם כן זה הוא ביטולם, וכן ישמעאל אמר כל עצמו של אביהם לסטים היה פירוש בחינת הרע הנקראת לסטים, ומעשיהם היה מגיד על בחינת נפשם מאיזה מקום באה. והנה עמון ומואב הוכיחו בטענתם מעיקר הוויתם שהיתה מבחינת הניאוף, אבל אדום וישמעאל לא הוכר הדבר מעיקר הבנין אלא ישמעאל על פי מלאך שאמר (בראשית טז יב) והוא יהיה פרא אדם ידו בכל הרי כי מגיד לה שורשו כי הוא זה, ועשו על פי יצחק כאומרו (בראשית כז מ) ועל חרבך פירוש שאתה מאותה בחינה. ואשא עיני ואראה חיבת הקודש הוא אדון ישראל אשר התנהג עם העמים בסדר זה להקדים לכל אחד מהם מצוה שיש להם טענה כנגדה, כי אולי שידע שיקבלו כיון שאין להם טענה כנגדה, ונתחכם ברוך הוא כדי שלא יטלו שכר על קבלת מצוה ראשונה שאין להם עליה מענה, ופתח דבריו להם רוממות אל להשמידם מנחלת שדי ובחר לו יה לעמו סגולה. והנה דרך זה אומרו **והייתם לי סגולה** הוא גזרת הפסוק, וכפי זה טעם אומרו בתוס' וא''ו, לתוספת שכר מלבד שאר פרטי המושג מהמעלות עוד לכם שתהיו סגולה כנזכר, ולא הוצרך להזכירם כי מובנים ממשמעות תוס' וא''ו של והייתם וגו'. עוד ירצה בתוס' וא''ו לרמוז ענין אחר, והוא כי לא יטעה לבבם לחשוב כי הוא האדון ברוך הוא חס ושלום צריך להם לשום דבר לא כן הוא אלא סגולה כמלכים שחפצים בדבר סגולה שהוא כלי יקר הגם שאין להם צורך בו, גם אתם תהיו לי אבן יקרה בערך כל העמים ולא שהדבר הוא אצלי לצורך **כי לי כל הארץ** פירוש ומעתה לא יוצדק לומר שיש לי צורך בדבר וכאומרו (איוב לה) אם צדקת מה תתן לו כי הכל שלו יתברך:
@32 **עוד** ירמוז למה שאמרו ז''ל (שבת קמ''ו.) ישראל שעמדו על הר סיני פסקה זוהמתן, וזו היא סגולתן מכל העמים שלא פסקה זוהמתן. עוד ירמוז סתר עליון לפי מה שקדם לנו כי ענפי הקדושה נתפזרו בעולם ואין מציאות להם להתברר זולת באמצעות ישראל וביותר באמצעות עסק התורה שהיא כאבן השואבת ניצוציה במקום שהם, ואותם נצוצי הקדושה גם להם יקרא סגולה, והוא אומרו **והייתם** קרינן ביה והויתם פירוש בה''א מלאפו''ם כי הם יהיו הוית סגולה **מכל העמים** אשר נפוצו שם באמצעות התורה כמאמרם ז''ל וכמו שכתבנו כמה פעמים הדברים במעשה מצרים. ואומרו **כי לי כל הארץ** כאן רמז שיש לו סגולה מפוזרת בכל הארץ, וזה טעם פיזור ישראל בד' רוחות העולם לחזר אחר הסגולה שהיא אבידתם. והנה זולת עונם של ישראל היו יכולים השגת הדבר בלא פיזור בעולם אלא בכח עוצם תורתם היו מולכים בכל העולם ושואבים כל בחינות הקדושות מכל מקום שהם, ובאמצעות החטא תש כוחם וצריכין לרדת שמה לברר הטוב ההוא:
@33 **ואתם תהיו לי וגו'**. צריך לדעת למה הוצרך לומר ואתם כיון שעד עתה להם היה מדבר. ואולי כי על משה ואהרן חוזרים הדברים, ולהיות שעד עתה היה מדבר על כל ישראל ועשאם סגולה אם כן יאמר משה כי אין הפרש עוד בינם לבין ישראל, לזה אמר **ואתם** פירוש אתה ואחיך תהיו לי ממלכת כהנים כנגד אהרן, **וגוי קדוש** כנגד משה ומשפחתו על דרך אומרו הקדשתי אתם [לי ואקח את] הלוים [וגו']:
@33 **או** ירצה לומר להם כי מעתה יהיו הם בבחינת פמליא של מעלה, כי למעלה יש להאדון משרתיו ומשמשים לפניו במרום ולהם יקרא כהנים גם יש לפניו צבא רב הנקרא קדוש דכתיב (דניאל ח') אחד קדוש, ואמר ה' כי אותם יעשה ה' במקום כהנים וקדושים העליונים, וכן היה שצוה לעשות לו בית לשכון בתוכנו ובחר ממנו כהנים וצוה לנו (ויקרא יא מד) והייתם קדושים, וכפי זה אומרו **ואתם** חוזר הדבר לכללות ישראל, והוצרך לומר תיבת **ואתם**, לבל יחשבו כי דבריו להם על העתיד לבא בעלות הנפש אחר הפרדה מהגוף ישיג הרוחניות מעלות הסדורות אבל בחיים חיותו תרחיק הדעת השגה זו, לזה אמר **ואתם** פירוש אתם בעצמיכם בעלי גויה תשיגו מעלה זו. ומצינו שהצדיקים השיגו מעלה זו שנקראים מלאכים וקדושים כי באמצעות התורה תגדל ותעלה מעלת האדם עד אין קץ למעלה מהמלאכים (סנהדרין צ''ג.), וזה לך האות כי ה' בחר ליותר מעלה לקדושת מקום כבודו עם ישראל הא למדת כי הם למעלה מהם כי מעלין בקודש וכו':
@33 **עוד** ירמוז לפי מה שפירשתי בפסוק והייתם לי סגולה שירמוז לבירורי ניצוצות הקדושה אומרו **ואתם** וגו' להגדיל מעלת המברר מהמתברר כי המברר יהיה ממלכת של כהנים ושל גוי קדוש שהם ב' הדרגות הקדושה המתבררים כנזכר, וחלקם לב' חלקים כי יש בנבררים הדרגות עליונים והדרגות קטנים כפי בחינת הקדושה, והכוונה בזה כי בחינת מלכות יש להם על המתבררים, וצא ולמד ממשה כי לצד שהוציא ישראל ממצרים קנה מלכות עליהם:
@33 **אלה הדברים וגו'**. כוונת הכתוב לפי מה שפירשנו בסמוך בפסוק ואתם תהיו לי על ישראל ידוייק הכתוב על זה הדרך שלא תחשוב כי אמירתי ואתם תהיו לי וגו' חוזרת עליכם משה ואהרן לא כן הוא אלא אלה הדברים אשר תדבר אל בני ישראל כי המעלות להם הנה, ולפי מה שפירשתי שחוזר על משה יכוין באומרו **אלה הדברים** וגו' שלא יוסיף עליהם. ואם תאמר פשיטא שלא יוסיף עליהם ואם יש לחושדו חס ושלום למה לא צוה לו בשאר המצות ששלחו עד עתה:
@33 **אכן** הכוונה היא שצוה לו שלא יפרש דברי ה' לישראל אלא יאמר הדברים כמות שהם, וטעם הבורא להיות שדקדק בדבריו ענין היראה וענין האהבה וכמו שפירשנום בפסוק (ג') כה תאמר וחש הבורא למשה שאחר שידבר דברי ה' להם יבא לבאר הדברים להוסיף זירוז מעצמו להכניס מוראו בלב ישראל או להפליג באהבת הבורא, לזה אמר אליו אל תדבר עוד בדבר הזה זולת **אלה הדברים** כי אם יאמר משה דברי יראה יבואו לעשות מצד היראה וה' לא כן יעץ ולא הזכיר היראה אלא כמי שמוסיף תבלין בתבשיל להוסיף בו טעם ערב וכמו שכתבתי שם שהוא לבל יזלזל אדם באיזה זמן באיזה פרט באומרו כי לא יקפיד האוהב אבל כל עיקר העבודה צריכה באהבה ונמצא דברי משה מפסיד חס ושלום הכוונה. עוד נראה כי רצה ה' לנסותם ושיער דברים המספיקים להם מהמוסר ומהאהבה לצורך קבלת התורה ואם לא תרוץ נפשם בשומעם דברים אלו זה יגיד כי רחוקים הם מטוהר לב, לזה אם יוסיף משה לדבר דברים רבים בין בבחינת היראה בין בבחינת האהבה הגם שיאמר בפירוש שהם דברי עצמו הרי הוא מפסיד כוונת הבורא בנסיונו הגם שיקבלו יש מקום לומר כי רצויו של משה הוא הסובב. גם יש בזה פחיתות חיבת התורה ושבח בית אביה האל הגדול, אשר על כן צוה ה' לבל יוסיף לדבר אפילו מפי עצמו דבר והבן:
@34 **ויקרא לזקני העם**. הנה נתחכם משה רבינו עליו השלום בשליחותו לעשותה בהתבוננות, כי ירא ופחד לבבו דלמא תארע תקלה בדבר שהוא תכלית הכל ועיקר העולם, וכבר אחזו חבלים לארץ שמא חם ושלום לא יקבלו ישראל את התורה, ונתחכם עליו השלום ולא דיבר לכללות העם עד שקרא לזקנים והושיבם לפניו וכל ישראל יחד שומעים דברי משה אלא שהקביל הדברים לפני הזקנים, והועיל בזה כדי שלא יתחילו להשיב למשה אלא הזקנים ולא כללות העם כי חש דלמא חם ושלום יענו מהעם תשובה שלא כהוגן מה שאין כן הזקנים מובטח הוא בהם שתשובתם תהיה כהוגן ואחר שישיבו הזקנים כהוגן העם יטו אחריהם, ולו יהיה כי יקהו שיניהם חס ושלום, כל זקן וזקן ידבר לבני משפחתו. ואולי כי בני אל חי נודעה להם התחכמות משה כי חש למיאון חם ושלום והוציאו עצמם מהחשד ולא הניחו לזקנים להשיב תחלה וענו כל העם יחדו כל אשר דבר ה' נעשה מדעתנו השלמה וברצוננו הפשוט ולא קדמה תשובת הזקנים לתשובת כל עם ה', והנה הראו בני ישראל עוצם אחדותם והשואת רצונם באלהינו כי ס' רבוא אמרו בהשואה דיבור אחד כאומרו יחדו ולא נתאחר אחד מהם ולא קדם אחד לחבירו ולא שינה אחד מהם להשיב בנוסח אחר אשרי עולם שאומה זו בתוכו. ובזה ידויק מאמר הנביא (ירמי' ב') כה אמר ה' זכרתי לך חסד נעוריך אהבת כלולותיך פירוש אומרו כלולותיך הוא תשובתם שענו כל העם יחדו שעשו ב' כלליות באהבה, הא' תשובה כהוגן מכולם ואין גם א' שלא נתרצה בדבר. ב' שהושוו יחד בקול התשובה ובלשון התשובה על דרך שכתבנו:
@34 **את כל וגו'**. נתכוון באומרו **את כל** שלא שינה מהודעת כל בלא מגרעת, ואומרו **האלה** שלא הוסיף לדבר דבר כמאמר ה' אליו (פסוק ו') אלא הדברים:
@35 **וישב משה**. פירוש לשון חזרה כי מלבד מה שקדמה הידיעה לבורא מתשובת ישראל כי הוא יודע נסתרות בכליות האדם ומכל שכן הנגלות עוד החזיר הדברים פעם ב', והטעם הוא לשבח התשובה כאשר אבאר בסמוך. או ירצה על דרך אומרם ז''ל (מכילתא) שאמר ה' למשה החזר לי תשובה, לזה אמר **וישב** פירוש כי לצד התשובה שאמר לו ה' השיבני וכו' הוא שעשה, כי זולת זה מי יגיד לפני יודע כל ברוך הוא:
@35 **את דברי העם וגו'**. אין הכוונה שהשיב שקבלו לעשות אלא השיב לה' אופן סדר התשובה שענו כולם יחדיו על דרך שפירשתי, ולא להודעה אלא נתכוין בזה לפאר לרומם עם בני ישראל על כמה בחינות טובות אשר תגיד אופן התשובה, ולזה החזיר משה הדברים לפני ה' על דרך אומרו (ד''ה א' י''ז) ומי כעמך ישראל גוי אחד:
@36 **הנה אנכי בא אליך וגו'**. אולי שיכוין לומר לו כי לצד שהיה ה' רגיל לדבר עמו פנים בפנים לזה אמר אליו שידבר עמו באופן אחר דהיינו **בעב הענן** ולא יהיה הדיבור כל כך רוחני כרגילות הקודם, ונתן הטעם **בעבור ישמע העם** כשידבר עם משה ואם ידבר כסדר הראשון באספקלריא המאירה אין כח בישראל לשמוע הדברים לעוצם רוחניותם, וה' חפץ שישמיע המאמרים לישראל, ואמר לו שמלבד תכלית זה שישמע העם המצוה מפי הבורא ויש בזה חיזוק האמונה בלבם עוד יש תועלת שיאמינו במשה לעולם בשאר מצות כשיצוה אותם על פי ה'. ונתכוין ה' בזה גם כן לרצות משה שלא יקפיד על המעטת כבודו מאופן הדיבור הרגיל:
@36 **יאמינו לעולם**. פירוש לעולם לדורות הבאים יאמינו באמצעותך בכל הנביאים על דרך שכתב רמב''ם בפ''ח מה' יסודי התורה וזה לשונו כל נביא שיעמוד אחר משה רבינו אין אנו מאמינים בו מפני האות וכו' אלא מפני המצוה שצוה משה בתורה ואמר אם נתן אות אליו תשמעון עד כאן. וכתב עוד שם כי אמונת משה לא היתה לצד המופתים וכו' אלא לצד ששמעו בדבר ה' עמו והם עדים באמיתות נבואתו. ועל פי הדברים יכולנו לפרש **וגם בך יאמינו לעולם** טעם אומרו לעולם רמז גם על שאר נביאים הבאים אחריו לעולם כשיבא גם כן נביא להם שלוח ממני יצדיקו נבואתו. כי האותות שיעשו לא יאמתו הנבואה אלא במצות ה' על אמונתם וזולת הבחנה זו גם המצוה במצוה זו יש בו פקפוק כשתהיה אמונתו על פי האותות זולת כשישמע העם בדברו עמו. אלא שיש לתת לב בדברי הרמב''ם איך יצדק לומר שלא האמינו במשה והלא כבר נאמר (לעיל י''ד ל''א) ויאמינו בה' ובמשה וגו' כי מופתיו ואותותיו מופלאים הם ומה גם מעשה קריעת ים סוף הוא דבר מבהיל ובו יצדיקו ויכריחו האמונה, הן אמת כי בשאר נביאים לצד שאין צריכין לעשות אותות חזקים וגדולים כאותות משה לזה צריכין אנו לחזק אמונת נבואתם על פי מאמר ה' אשר צוה לשמוע לו מה שאין כן משה. ומה שכתב רמב''ם שם כי אותות שעשה משה לא היו כדי שיאמינו בו אלא לצורכי ישראל וכו' כאמור שם, סוף כל סוף ישתמע האמת מעצמו כי משה אמת:
@36 **ונראה** לומר כי האמונה שהאמינו ישראל במשה היתה שהוא עבד ה' וה' חפץ בו ועושה תפלתו ורצונו אך לא האמינו שהיה ה' מדבר עמו, כי יש סברא מחכמי אומות שמוכיחים בהרבה הוכחות כפי פילוספיותם כי מן האי אפשריות שידבר ה' עם אדם וחי, ואלה יצדיקו כי ה' ישמע ויענה ויאהב לחביביו ויעשה רצונם, ולצד שיש סברא זו בעולם נוכל לומר כי הגם שהאמינו ישראל במשה עבדו פירוש שהוא עבד ה' וישמע ה' תפלתו ויעשה חפצו ורצונו אבל לא מפני זה יצדיקו כי ידבר ה', וישנה עדיין לחששת פילוסופי האומות, לזה אמר ה' אליו **בעבו** ר **ישמע העם בדברי עמך** ובזה יצדיקו כי ידבר ה' עם האדם וחי, ואומרו **וגם בך יאמינו** פירוש באמצעותך יאמינו בנביא אשר אקים להם תחתיך בכל דור ודור לעולם כי תפקע מהם טענת סברא זו. או ירצה אומרו **בך** באמצעות נבואתך כשיצדיקוה כשתצוה להם שישמעון לנביא על פי אות יאמינו לעולם לכל נביא ונביא אבל זולת הצדקת נבואתך לא יועיל האות להאמין בנביא כמו שכתב הרמב''ם. אחר שכתבתי זה מצאתי ברייתא במכילתא וזה לשונם גם בך גם בנביאים שאחריך עד כאן, והם דברינו עצמם ובמה שפירשתי תבין כוונת דבריהם. והנה בשמוע העם דברי ה' הצדיקו כולם יחד כי ידבר ה' עם האדם וחי וכמו שהגידו בפיהם ואמרו (דברים ה' כ''א) היום הזה ראינו כי ידבר ה' עם האדם וחי והם עדי ה' בדבר ונכזבה דעת הפילוסופים בראיה ברורה, וגם הכירו מעלת הנביא משה במשה שנשאהו ה' בנבואתו דכתיב (פסוק י''ט) משה ידבר והאלהים יעננו בקול וכמו שדרשו ז''ל בכתוב (מכילתא) יעויין שם דבריהם:
@36 **ויגד משה וגו'**. אולי שהגיד שהסכימו לשמוע דברי ה' מפיו כמאמר ה' בעבור ישמע העם וגו', או שאין צריך עוד אות להאמין במשה שכבר האמינו במשה כי הוא נביא. ומכוון ההגדה היא, לימוד זכות על ישראל לבד, ולדבריהם ז''ל (מכילתא) שאמרו שההגדה היא שאמרו ישראל רצוננו לשמוע מפי ה', ולמאן דאמר לראות את מלכנו ידוייק לשון הגדה שהם דברים קשים שיבקש עבד לשמוע קול אלוהו או לראות כבודו יתברך. והגם כי מצינו שאמר ה' בעבור ישמע העם לא אמר שידבר עמהם אעל בדברו עם משה ישמעו הם ובקשתם היתה שידבר ה' עמהם, וטעם ההגדה הגם שלא יכחד ממנו דבר הוא להשיבו על שאלתם. ומצינו לו שהשיב תכף ומיד לך אל העם וקדשתם וגו':
@39 **והגבלת וגו'**. נראה שאין מצות הגבלה זו אלא ליום הג' ואף על פי כן הקדימה מעתה כדי שינהגו בו כבוד מעכשיו, גם ירגילו עצמם להתרחק ממנו בג' ימים, ואין לומר שינהוג חיוב הנגיעה בהר מיום צוותו, זה אינו כי הוא דבר רחוק שיתקדש ההר ויתחייבו עליו קודם רדת שכינתו ית'. וכן משמע ממתניתא בספרי (מכילתא כ''ד) כי לא התחיל החיוב אלא מיום ג':
@44 **ויוצא משה וגו'**. אולי שלצד חרדתם פחדו מן ההר והוציאם משה והעמידם בתחתית ההר לקבל התורה מעומד:
@45 **עשן כולו**. פירוש ששלט האש בגופו של הר ונשרפו אבניו כמשפט הכבשן אשר ישרפו בו האבנים לעשות סיד, ומעתה אבני סיני נעשו סיד, ואומרו **ויחרד כל ההר** כי כן דרך האבנים כששולט בהם אש בכבשן יתזעזעו וישמיעו קול חרדה:
@46 **משה ידבר והאלהים וגו'**. אולי שהיה משה מדבר לפני ה' דברי שיר ושבח כמקבל פני מלך הגדול ברוך הוא, **והאלהים יעננו בקול** פי' בקול האמור בסמוך שהוא קול השופר כמי שמתרצה בדבריו. או יאמר **יעננו** למה שהיה מדבר לו ואומרו **בקול** פי' בקול גדול בעבור ישמע העם בדברו עמו כמו שכתבנו למעלה שבזה יצדיקו נבואתו. ורואני כי יש בזה תוספות הדרגה כי היה ה' עונה לדברי משה וזה יותר מעלה ממה שהיה ה' מדבר תחלה ויענהו משה. ורבותינו ז''ל אמרו (מכילתא) שיכוין על הדברות ששמעו מפי משה שהיה ה' מגביה קולו של משה וכו', וזה דרך דרש וכפטיש וגו':
@47 **וירד ה' על הר סיני**. רבותינו ז''ל אמרו (סוכה ה'.) למעלה מעשרה. וצריך לדעת למה הוצרך לומר **אל ראש ההר** כיון שהגבוה הוא עשרה מההר פשיטא שאפילו לראשו לא הגיע. ואולי כי בא לשלול שלא ירדה שכינה לצדדי ההר ואפילו למעלה מעשרה, הגם שמצינו לו שאפילו במקומות הנמוכים ירדה שכינה כל שיש ממנה לארץ י' טפחים, וצא ולמד מהמשכן בכל מקום אשר יחנו בני ישראל ישכון שם כבוד ה', כאן בהר לא ירד אלא על ראש ההר, ולזה מצא משהעלות אל ראש ההר, וכאומרו בסמוך ויקרא ה' למשה אל ראש ההר. וצריך ליישב עדיין למה לא אמר הכתוב וירד ה' על ראש הר סיני. ואולי שחש לטעות בכוונת דבריו, כי לעולם ירד על כללות הר סיני ראשו וצדדיו ואומרו על ראש לצד שלא השרה שכינתו ממש על ההר בבחינת כל חלק וחלק מההר יקרא מקום שכינת ה' שמה ראש להיותו עליון ממנו והבן, לזה אמר בסדר זה **וירד ה' על הר סיני** למעלה מעשרה ואחר כך חזר להוריע מקום שירד שמה שהוא **אל ראש ההר** והבן:
@47 **עוד** ירצה על פי דבריהם ז''ל שאמרו (מכילתא פ''ט) כתוב א' אומר מן השמים וגו', מלמד שהרכין ה' שמים העליונים וכו' והציען על גבי ההר ודבר עמהם עד כאן. וזה הוא שיעור הכתוב **וירד ה' על** וגו' פירוש לא ירד ממש אלא למעלה כרמוז בתיבת על ושמיו מקום מצבו היו נוגעים אל ראש ההר:
@47 **עוד** ירצה להודיע כי כשירד ה' פירוש כשהתחיל להוריד שכינתו רעש ההר ועלה לקראתו כעבד רץ לפני רבו, וזה הוא שיעור הכתוב **וירד ה'** ועדיין לא גילה הכתוב לאיזה מקום ירד והודיע פעולת ההר הגם היותו דומם שנעשה בעל חי ועלה קודם שיגיע עדיו, ואחר כך הודיע הכתוב לאיזה מקום ירד ואמר **אל ראש ההר**, הא למדת שעלה ההר קודם הגעת שכינת ה' אל ראשו:
@48 **פן יהרסו וגו'**. פירוש לבל יחשבו בדעתם כי יראו ברוך הוא הגם שימותו על דרך אומרו (תהלים ס''ג) טוב חסדך מחיים ומיתתם זו היא חיותם, והוא אומרו **פן יהרסו** פירוש יסכימו על הריסתם **אל ה' לראות** פירוש כאלו אמר לראות אל ה', ואומרו **ונפל ממנו רב** פירוש תהיה נפילתם נפילה רבה מלבד שימותו תהיה להם נפילה אחר נפילה. או ירצה כי לצד שאורו יתברך ממלא המקום כשיבואו לראות יצטרך ה' לסלק האור ההוא לבל יביטו בו, וזה הוא אומרו **פן יהרסו אל ה'** פירוש לאורו לסיבת ראותם, והרי זה מגיד כי לא ישיגו לראות אם יבואו לראות, ולזה לא אמר הכתוב פן יראו כי לא ישיגוהו כנזכר אלא הם יחשבו בדעתם לראות, ושמא תאמר אין כאן לא הקרבת התועלת ולא נזק לזה אמר **ונפל** וגו' פי' מלבד שלא יראו עוד להם הקרבת הנזק. ודקדק לומר **רב** פירוש אפילו יהיה הרב שבהם לא יאמר שלא אקפיד אלא על המון העם אבל גדולי ישראל הראוים להשראת שכינה לא אקפיד תלמוד לומר ונפל ממנו רב:
@49 **וגם הכהנים**. פי' הגם שיש להם מעלת קריבה אל מקום המקודש לעבוד בבית ה' כאשר היה מקובל בידם או הבכורות או מזרע אהרן, **יתקדשו** פי' לא תהיה קדושתם מגעת עד גדר זה וצריכין הם לחשוב עצמם בערך מקום זה כאילו אין להם קדושה כל עיקר. ושיעור תיבת יתקדשו כשיעור תיבת ודשנו (במדבר ד' י''ג.) או ירצה על פי דבריהם ז''ל (מכילתא) כי הגביל ההר עד כאן משה עד כאן גבול אהרן עד כאן גבול הכהנים, כפי זה אומרו **הנגשים אל ה'** פירוש שגבולם בהר נגשים מה שאין כן ישראל, **יתקדשו**, פי' יעמדו בקדושתם ולא יוסיפו לעלות עוד פן וגו':
@50 **ויאמר משה וגו' לא יוכל וגו'**. צריך לדעת תוכן משמעות ענין ההפרש בין משה ובין ה' כי ה' אמר לו רד העד וגו' ולא הספיק מה שכבר צוה קודם ומשה מקשה ואומר כי אינו צריך ודי במה שקדם מהציווי וההתראה. ונראה כי מתחלה צוה ה' על ישראל לבל יעלו ולבל יגעו בהר בדרך כלל וכשחזר ה' לומר למשה שיתקדשו הכהנים ורמז לו שיש להם מקום בהר לעמוד בו וכמו שדייקנו מאומרו הנגשים אל ה' יתקדשו חש שישראל ידונו בדין זה דין דבר שהיה בכלל ויצא מן הכלל שללמד על הכלל יצא והכהנים והעם ואהרן הכל בכלל נגיעת ועליית הר היו וכשיצאו כהנים להתיר חלק בהר ללמד על הכלל יצא ויותרו כל ישראל בחלק שהותרו בו הכהנים ולפחות בחלק שלמטה ממנו בהדרגה, והגם שעדיין לא נתנה תורה לדעת משפט זה אפשר שימצא בתוך ס' ריבוא ישראל חכם שידין בחכמתו כזה. או לו יהיה שלא ידון אדם דין זה מדעתו עם כל זה ה' אוהב משפט צדק ולא יכול לחייבו מיתה לנוגע בהר במקום עמידת הכהנים אחר שכפי משפט התורה פטור הוא כנזכר, לזה חזר ה' לומר לו רד העד בעם ובזה סתר שאין לדון בדין זה דבר שהיה בכלל שהרי גילה הדבר בפירוש לאסור חלק ההר שיעלו בו הכהנים, ומשה לא הבין דברי ה' וכוונתו כמו שפירשנוה כי עדיין לא גילה לו ה' מדות שהתורה נדרשת בהם וסבר כי דוקא אהרן והכהנים שהתירם ה' אבל ישראל באיסורם עומדים ולזה צעק לבו כי אזהרה זו אינה צריכה כי לא יוכל וגו' שכבר העדותה בנו, והשיבו ה' לך רד ועלית אתה וגו' ועל פרטי המקומות שאני מתיר לך ולאהרן ולהכהנים אני מזהירך שתעד בהגבלתם הרי זה מורה באצבע כי לצד מה שגילה בהם ההתר הוא שהוצרך לחזור לאוסרם:
@50 **ולפי** מה שפירשנו באומרו הנגשים וגו' שהכוונה הוא הנגשים לעבודת המשכן גם כן יהיה טעם חזרת האזהרה כמו שפירשנו לצד דבר שהיה בכלל אלא כי עדיין לא גילה ה' היתר עליית אהרן והכהנים שמצדה הוצרך לחזור פעם ב' האזהרה ותיכף קדם משה קודם שיגמור הדבור של היתר עליית הכהנים ואמר **לא** י **וכל** וגו' וחזר ה' והודיעו התבוננות הדברים ואמר לו **לך רד ועלית אתה** וגו' והכהנים הרי התיר חלק מעליית ההר ותיכף סמוך ממש אמר לו **והעם אל יהרסו** פירוש כל עיקר והכהנים לא יהרסו למקום אהרן ואהרן למקום משה ואז השכיל דעת עליון על דרך שפירשתי שהמיחוש הוא לבל ידונו דבר שהיה בכלל וכו', ורמזו אל עליון בסדר הדיבור שהקדים לומר לו **ועלית** וגו' **והכהנים** וגו' ואחר כך **והעם אל יהרסו** וגו'. ובזה מצאנו נחת רוח במאמר ב' שאמר ה' למשה **ועלית אתה** וגו' וקשה ממה נפשך אם הודה לו ה' על תשובתו אם כן למה חזר לומר פעם ב' והעם אל יהרסו, ודבר זה פשוט הוא כי כוונתו היא שיאמר כן לישראל אם כן לא נתקבלה תשובת משה, ואם נאמר גם כן שלא הודה על דברי משה למה לא השיבו תיכף לסתור דבריו עד שהקדים לומר ועלית אתה ואהרן והכהנים כי היה לו לה' לגמור ענין השליחות שהתחיל לצותו עליו שאמר לו העד בעם וגו' ואחר כך יצו האל דבר חדש שהוא ענין עליית אהרן והכהנים שלא הזכירו עד עתה, ובמה שפירשתי יבא על נכון כי לעולם לא באה מצות העד בעם אלא לצד היתר גבולין של אהרן אלא שלא המתין משה עד גמרן של דברים ולזה בדברי ה' אליו הקדים תשלום הדברים שלא הספיק משה לשומעם שהוא טעם האזהרה ואמר לו **ועלית אתה ואהרן והכהנים** הרי התיר גבול מההר לאהרן וגבול לכהנים וגמר אומר **והעם אל יהרסו** לגבולין של אהרן והכהנים אלא כל ההר באיסור:
@50 **עוד** נראה לומר טעם ההתראה פעם ב' להיות כי התראה ראשונה לא נאמר בה זמן מאימתי מתחיל האיסור, והגם שהזכיר שם ג' ימים לא נאמרו בפירוש בענין איסור הגבלת ההר שמתחיל מיום הג' ונמצא שעדיין לא ידעו ישראל זמן התחלתה, לזה כשירד ה' תכף אמר למשה שירד להעד וגו' שהוא משעה זו ואילך, ותשובת משה צריך עיון. ואולי כי משה חשב כי איסור הגבלת ההר היא מעת צוותם כיון שלא נתבאר בפירוש לא תגע בו יד ביום פלוני התחלת המצוה היא מעת האזהרה, ולא כן היה דעת עליון, ולזה היה עליו דבר ה' חזק לחזור לומר כי זה הוא זמן ההגבלה. ולכשנאמר כי כן היתה דעת עליון שאיסור נגיעת ההר יתחיל מעת צוותו טעם שהוצרך האזהרה פעם ב' כי בפעם ראשונה אמר כי סקול יסקל או וגו' הרי זו מיתת בית דין וכאן חידש כי מי שלא הרגוהו ישראל שה' יפרוץ וגו', ודקדק לומר לשון רבים לומר שהגם שיהרסו כולם לראות ידינם בדין שמים ויפרוץ בם ה':
@51 **רד ועלית וגו' עמך**. כפל לומר **לך רד**, אחת לגופה ואחת לומר לו לשון ירידה ואולי שהירידה היא מקודם לא היה למשה מקום מוקבל בהר והיה עולה לראש ההרה וכשסרב אמר לו **רד ועלית** וגו' פי' כשם שאהרן יש לו גבול גם אתה יש לך גבול והוא אומרו עמך הרי השוה האחים בבחינת הגבול:
@53 **וידבר וגו' את כל הדברים וגו'**. טעם זכרון שם אלהים בנתינת תורה, לומר כי התורה נתנה ממדת הדין וממדת הרחמים, מדת הדין **וידבר אלהים**, מדת רחמים **אנכי ה'**, עוד הודיע סוד אומרו (מ''א י''ח) ה' הוא האלהים, כי דבר אלהים אנכי ה', והוא מה שאנו מיחדים פעמים באהבה בפ' שמע ישראל ה' אלהינו ה' אחד:
@53 **עוד** יתבאר על דרך שאמר רב קטינא (מנחות מ''א.) ענשיתו אעשה וכו' עד כאן, הרי שעל עשה לא יעניש הכתוב, לזה אמר ה' כי יביא ה' במשפט עונש על כל הדברים גם לעשין הרשומים בי' הדברות, אמונתו ית' שהוא עיקר הכל הרשומים בתחלת דבר ה' אנכי וגו', שבת, כבוד אב ואם, על אלו הגם שהם עשה יש אלהים שופטים בארץ, והוא. אומרו **וידבר אלהים** שהוא בחינת הדין את כל הדברים בין עשה בין לא תעשה:
@53 **עוד** ירצה באומרו **את כל הדברים** לומר כי אין חפץ במקבל תורה אלא אם יקבל כל התורה, וכל המקבל עליו תורה חוץ ממצוה א' אין לו תורה (בכודות ל:):
@53 **עוד** ירצה על פי ממה שהקדמתי בפ' בראשית כי כשידבר ה' בתגבורת המכונת לשם אלהים ידבר דברים מופלאים אשר אין הפה יכול לדבר והוא שיאמר הדברים שלימים וכן רבים בדבור אחד כאשר עשה בבריאת עולם, כמו כן ביום מתן תורה דיבר בתגבורת את כל הדברים בדבור אחד, ואומרו תיבת **לאמר** יתבאר בהעיר מה שיש להעיר בנוסח עשרת הדברים מדוע שינה הכתוב נוסח דיבור מדיבור כי בתחלה התחיל לדבר בסדר זה **אנכי ה' אלהיך**, **הוצאתיך**, **על פני**, כי ה' הוא המדבר על עצמו יתברך שמו ואחר כך יצא לדבר בדרך אחר **את שם ה' אלהיך**, **לא ינקה ה'**, **שבת לה' אלהיך**, **כי ששת ימים עשה ה'**, שהיה לו לסיים כדרך שהתחיל על זה הדרך לא תשא את שמי, כי לא אנקה, כי ו' ימים עשיתי וגו':
@53 **אכן** יתבאר על דרך אומרם ז''ל (מכות כ''ד.) אנכי ולא יהיה לך מפי הגבורה שמענום פירוש בתגבורת הדיבור יובן כי כאשר דיבר ה' עשרת הדברים בדיבור אחד כמו שכתבנו בסמוך אין האוזן יכולה לשמוע כל הגבורות וכשהשמיעם לישראל השיגו הם שמוע ב' דברות מהם שהם דיבור אנכי וגו' ודיבור לא יהי' לך ויצתה נשמתם כאומרו (שה''ש ה') נפשי יצאה בדברו ולא יכלו הבין עוד ושאר הדברות נחצבו להבות אש מקולו יתברך ועמדו סדורים על הר סיני עד שחזרה נשמת ישראל בטל חיים באו הדברות שהם קולות האדיר ברוך הוא והיו מדברות לכל א' מישראל, ולזה תמצא שאנכי ולא יהיה לך נחקקו בתורה כסדר שאמרם ה' **אנכי ה' אלהיך אשר הוצאתיך** כי האלוה בכבודו מדבר נוכח לישראל בעד עצמו ברוך הוא וכמו כן במצות **לא יהיה לך** גם כן ידבר כסדר זה אבל משם ואילך ידבר קולו יתברך בעד מלאכו כאומרו **שבת לה' אלהיך**, **כי ששת ימים עשה ה'**, **על כן בר** ך ה', וגו' וכן כולם, כי אינו יכול הקול לומר שבת לי וגו', עשיתי את השמים וגו' ונתתי וגו', כי אינו אלא מלאכו ית' והבן ויערב לחכך. והגם שאמרו ז''ל (מכות כ''ג:) כי משה אמרם לישראל, אפשר כי משה היה בו כח ושמע כולם וכשבאו הקולות לדבר לישראל היה קולו של משה גם כן מדבר. ואולי כי לזה רמז הכתוב באומרו (לעיל י''ט י''ט) משה ידבר והאלהים יעננו בקול, ותמצא שאמרו ז''ל (שהש''ר פס' ישקני) שכל דיבור ודיבור היה עומד על כל אחד ואחד מישראל ואומר לו תקבלני עליך והוא אומר לו הן ומחבקו ומנשקו ועולה ומתעטר על ראשו, ולפי זה יתיישב אומרו **לאמר** על זה הדרך **וידבר אלהים את כל** וגו' פירוש בתגבורת האלהים ודיבר כולם בדיבור אחד גם עשה כח בדברות שהם בעצמם יאמרו לישראל כשיצטרכו כמו שכן היה כי כשלא יכלו ישראל לשמוע כולם מהגבורה דברו הם אליהם כמו שכתבנו:
@53 **עוד** יכוין באומרו **לאמר** כי יש בסדר זה שנדברו בו הדברים מעלה ורוממות לישראל על דרך אומרו (דברים כו יח) וה' האמירך וגו' כי הרבה תועליות נמשכו מזה שפסקה זוהמתן וזה יסוד קניית הקדושה בהם לעולם:
@53 **עוד** יתבאר הכתוב על דרך אומרם ז''ל (תנחומא תולדות) שאין הקדוש ברוך הוא מייחד שמו על הנבראים בחיים חיותם משום (איוב טו) הן בקדושיו לא יאמין, ולזה לא יחד שמו על אברהם לומר עליו אלהיך אלא אחר מותו, והוא אומרו **וידבר אלהים את כל הדברים האלה** פירוש בתגבורת הדיבור כמו שפי' דברים שאין האוזן יכולה לשמוע, והטעם הוא **לאמר** להם אנכי ה' אלהיך פירוש ליחד שמו על כל אחד ואחד מהם לומר לו אלהיך אשר על כן השמיעם את קולו ליסרם להפריד מהם הזוהמא ובזה יהיו ראוים לומר להם כן. ולדברי רבותינו ז''ל (שבת פ''ח:) שאמרו שפרחה נשמתם נמצאת אומר כי כשיחד שמו עליהם היה זמן יציאת נשמה אז אמר לכל אחד מהם אלהיך, והגם שהיו בחיים ושמעו גם כן לא יהיה לך וגו', לא יתייחס לה איחור כי הכל אמר ה' בדיבור אחד ולא קדמה אפילו אות לחברתה. עוד אומרו **לאמר** יכוין אומרם ז''ל (זהר ח''ב צ''ג:) שכל התורה כולה רמוזה בעשרת הדברות, והוא אומרו **לאמר** פירוש דברים אלו יש בהם אמרות אחרות כלולות ורמוזות. וראיתי לתת טוב טעם בהשמעת ה' לישראל ב' דברות אנכי ולא יהיה לך כי הם ב' שרשים לב' כללות המצות מצות עשה ומצות לא תעשה, **אנכי** היא עיקר ושורש כל מצות עשה, **לא יהיה לך** וגו' היא עיקר ושורש כל מצות לא תעשה, לזה נטע ה' בהם מפי אל עליון שרשי ב' עיקרי המצות שבזה לא תימוט תורה מזרעינו לעולם ועד:
@54 **אנכי ה' אלהיך וגו'**. טעם כפל אשר הוצאתיך **מארץ** וגו' **מבית עבדים**. פשט הדברים הוא שכוונתו להגדיל עוצם שבייתם שהיו בארץ מצרים מקום שאסיריו לא פתח (ישעי' יד יז) וגו' נוסף על הפלגת טומאתה, ועוד שהיו שם בגדר עבדים והוציאנו ה':
@54 **עוד** יכוין ה' לומר על זה הדרך **אנכי ה' אלהיך** הנה הזכיר בתחלת דברי ה' ב' עניינים האחד היותו ה' ברוך הוא שם הוי''ה זה יגיד האמונה כי ממנו יתברך ובמאמרו היה כל הווה וכל מה שהיה ומה שיהיה, גם יגיד על הוויתו יתברך היה והווה ויהיה, והב' אמר אלהיך פירוש שעליהם לקבל מאמרו וגזרותיו, וכל הממרה את פיו יכנו אלוה, וכנגד ב' בחינות אלו בא האלקים להכריח כל אחת מהם בהוכחה שאין עליה טענה, כנגד אומרו **אנכי ה'** זה לך האות **אשר הוצאתיך מארץ מצרים**, דע כי באמצעות יציאת מצרים הוכחשו כל הדוברים שקר שיש חס ושלום אמונה זולתו כי הוכחשו המאורות כי לא אלהים המה בהחשיך ה' מאורם, הוכחושו הימים כי ה' עשה בהם אותות והפכם לדם, הוכחשה הארץ בהכותה ה' ותשרץ שרצים רעים, הוכחושו בעלי חיים שאין בהם ובמזלם חוזק, הוכחושו כל אלוהות בעשות ה' בהם שפטים, הרי כי ה' הוא אדון כל הווה ושולט על הווה ומכחידו וגוזר על אין ויהיה כאשר עיני כל ישראל רואות. וכנגד מה שאמר **אלהיך** שצריכין לקבלו עליהם לאלוה לקיים כל דבריו אמר טעם הדבר **מבית עבדים** פירוש כי לצד שהיית עבד לזולת ואני הוצאתיך מעבדותם שורת הדין נותנת כי תקבל אלהותי עליך לקיים כל דבר:
@54 **עוד** ירצה בכפל **מארץ מצרים מבית עבדים** להודיע סוד כמוס כידוע ליודעי חן כי נשמות ישראל שיצאו ממצרים הן הנה שהיו טבועים בטומאת מצרים ובאמצעות יעקב אבינו ובניו אשר ירדו מצרים הוציאו אותם כאומרו (בראשית מו ג) כי לגוי גדול אשימך שם. ועיין מה שפירשתי שם, ואמרו יודעי נסתרות לה' כי הוא עצמו שאמר הכתוב עליו (דברים ד' ז') כי מי גוי גדול וגו' שעמדו בהר סיני. וכפי זה יתבאר הכתוב על נכון אומרו **אשר הוצאתיך מארץ מצרים** הוא הוצאות הנשמות משבייתם בטומאת מצרים פי' שבררם באמצעות מועצותיו ית', אבל עודם במצרים בבית עבדות, ואמר **מבית עבדים** כנגד מה שהוציא העם המבורר לבל ישתעבדו בהם שונאיהם:
@54 **עוד** ירצה על דרך אומרם ז''ל (ירושלמי סוכה פ''ה ה''ד) בפירוש יושב תהלות ישראל כי לא נתרצה הקדוש ברוך הוא בתהלת מהלליו כשאמרו אלהי עולם ולא אלהי המלאכים אלא כשאמרו ברוך ה' אלהי ישראל, והוא אומרו **אנכי ה' אלהיך** פירוש שלא נתרציתי בשום כינוי המעלות אלא בקריאתו אלהיך ובזה פרסם מעלות ישראל בעליונים, וכנגד פרסום בתחתונים אמר **אשר הוצאתיך** וגו' פי' מקום שאין מציאות לצאת משם והיתה הוצאתיך פרסום גדול לכבוד ולתפארת, וצא ולמד מדברי יתרו שהוא אחד המיוחד מהאומות. ואומרו **מבית עבדים** פירוש לא הוצאתיך בדרך שישאר עליך שם עבדות, המשל אם היה ה' מוציאם בדרך בריחה וכדומה הגם שהיתה ההצלה נכונה אף על פי כן שם עבדות לא יעקר מהם כי אלה עבדי פרעה, וממה שהוציאם בכמה נוראות עד שאמר פרעה הרי אתם לעצמכם הרי אתם בני חורין כו' (ילקוט ר''ח), ועוד לו כשרדף שעשה ה' הפלא הגדול בהטבעתו בים בזה פקע שם עבדות מהם:
@54 **עוד** ירצה לדבר עם הנפש ועם הגוף, כנגד הנשמה אשר תכיר בחי' הרוחניות אמר **אנכי ה' אלהיך** כי הנשמה תכיר בחינת האלהות, ואולי באותו רגע עצמו היתה יציאת הנפש והכירה אלוה שלה כשאמר לה אנכי, ולזה אמר לשון יחיד **אלהיך** כי בחינת הנשמות הקדושות מתאחדת היא ואין בהם פירוד בעולם הפירוד שהוא עולם הזה, ותמצא שאמר דוד בדברי הימים (א' י''ז) ומי כעמך ישראל גוי אחד בארץ פירוש אפילו בארץ במקום הפירוד הם גוי אחד כי נתקדשו ונעשו בארץ כמלאכים והוא השבח שמשבחם בו דוד עליו השלום, וכנגד בחינת הגוף וחיותו שהוא בחינת הדומה לחיות הבהמי אמר הכרת חסד עולם הזה כי לא תוכל בחון בחשק רוחניות הנאור:
@54 **עוד** ירצה **אנכי ה' אלהיך** פי' קודם ביאתך לעולם הזה כי אתה אור מאור הקדוש חלק ה' כאומרו (דברים לב ט) חלק ה' עמו, ובחינה זו תגידנה תיבת אלהיך כי לא יתיחס דבר זה אלא לבחי' הקדושה שהוא מאורו יתברך כידוע ליודעי חן וכנרמז ברובי מאמרי רז''ל. ואומרו **אשר** וגו' פירוש אשר על כן הוצאתיך מארץ מצרים, ובזה הגיד טעם אשר הרעים והרעיש ה' תבל ויושביה שמים וצבאיה בשביל ישראל להוציאם כי מהנמנע שיציל חלקי הקדושה ולקרבם אליו:
@54 **עוד** ירצה על זה הדרך **אנכי ה'** פירוש בין בזמן שאני מתחסד עמך אהיה לך לרבון בין בזמן שאני מיסרך ומוכיחך אהיה אלהיך:
@54 **עוד** ירצה על דרך אומרו (תהלים קטז) כוס ישועות וגו' ובשם ה' אקרא צרה ויגון וגו' ובשם וגו', ודרשו ז''ל (ברכות ס':) מברכין על הרעה בשמחה כשם וכו', והטעם כי בחינת המוסר מה' אינו אלא לצד הטוב והחסד, והוא אומרו **אנכי ה'** פירוש מדת החסד והרחמים אפילו כזמן אלהיך פירוש שאני מיסרך:
@54 **עוד** ירצה באומרו **מארץ מצרים מבית עבדים** על זה הדרך אני אשר הוצאתיך מארץ מצרים אני עתיד להוציאך מבית עבדים, וזה ירמוז על גלות האחרון אשר שעבדו בישראל כל אומה ולשון כמשפט הרגיל בעבד ורמז ה' כי יוציאנו מבית זה:
@54 **עוד** ירצה על זה הדרך **אשר הוצאתיך מארץ מצרים**, ואם תאמר ולמה הוצאתנו משם ולא הגדלת חסדך עמנו שהיה ה' ממשיל ישראל שם בארץ אויביהם ויעבידו בעובדיהם וישלטו בהם ויקחו את ארצם מידם וישבו בה לעיניהם ויש בזה יותר נחת רוח לישראל והגדת עוצם היכולת כי יש אלהים שופטים בארץ ושולטים בה, לזה אמר ה' כי טעם הדבר הוא לצד שהארץ היא בית עבדים פירוש על דרך אומרו (דברים לב א) בהנחל עליון וגו' יצב גבולות עמים, ואמרו ז''ל (זהר ח''א ק''ח:) כי ה' חלק מקומות העולם לשרי מעלה זולת ארץ כנען אשר בחר לו לשמו כביכול, והוא אומרו **מבית עבדים** פירוש מקום שהוא של עבדים של ה' פירוש שממשלתו ממשלת שר אחד מעבדי ה' ולא רצה ה' שיהיו ישראל תחת ממשלת השרים אלא תחת ממשלתו יתברך בכל והוציאם מארץ מצרים לצד שהיא בית עבדים לתת להם ארץ אשר היא בית אלהים:
@55 **לא יהיה לך וגו'**. פירוש לצד שקדם לצוות על אמונתו יתברך והוא דבר שעיקרו בלב לזה אמר כי כמו כן יצטרך להרחיק מלבו אלהות הזולת הגם שלא יוציאנו בשפתיו, והוא שדקדק לומר בתיבת **לך** פירוש אפילו במחשבתך, וכפי זה מצינו אזהרה למחשבת עבודה זרה שאמרו ז''ל (קידושין ל''ט:) בפסוק (יחזקאל י''ד) למען תפוש וגו' שה' מעניש על מחשבת עבודה זרה ואמרו ז''ל (זכחים קו:) אין עונש בלא אזהרה, הרי לך אזהרתו:
@55 **עוד** ירצה לומר כי כל עבודה זרה שבעולם אין פעולת העובד פועלת הדרגה בנעבד לעשותו אלהים כאשר תעשנה פעולת איש ישראל כי נותן כח גדול בבחינת הרע וכופה חם ושלום בחינה המעולה לפני בחינת הרע רחמנא ליצלן, והוא אומרו **לא יהיה לך אלהים** פי' הויה שלך תעשנו אלהים:
@55 **עוד** ירצה כי באמצעות העובד הוא ממציא הויה אחת שהיא אלהים מה שלא היה כן קודם:
@55 **עוד** ירצה לומר כי אל זר אשר יעשה האדם זולתו יתברך הוא השופט נקמה מעובדהו על דרך אומרו (ירמי' ב') תיסרך רעתך:
@55 **עוד** ירצה כי בעשותו אל זולתו יתברך מהנמנע שיהיה לו אחד והגם שהוא לא ירצה לעבוד אלא לאחד. יתחייב לעשות רבים כי אין אחד, והוא אומרו **לא יהיה** לשון יחיד וגמר אומר אלהים אחרים. או ירצה לומר כי כשיתחיל לעבוד אחד לסוף יעבוד רבים. וצא ולמד מדברי נביאי ישראל (סנהדרין ק''ב:) ריבוי האלוהות שהיו ישראל עובדים בארץ בעונות. ואומרו **על פני** יתבאר על פי מה שכתב רמב''ם בפ''ט מה' יסודי התורה כי יאמן נביא בדבריו אם יאמר לעבור על מצוה אחת ממצות התורה לפי שעה על פי ה', ודוקא בשאר מצות חוץ מעבודה זרה שאפילו לפי שעה הרי זה נביא שקר ובן מות הוא, וזה הוא אומרו.
@55 **על פני** פירוש בכל פרטי הזמנים, כי כבר הקדים הודעתו יתברך בהזכרת שמו כי הוא היה והווה ויהיה באין הפסק, ומעתה הרי זה הכניס בכלל האיסור כל הימים והשעות והרגעים שכולם בכלל איסור לא יהיה:
@55 **עוד ירצה באומרו על פני** רמז לשלול טענת כת הטועים שעושים עבודה זרה לאמצעי לטענת שלילות המצאו חם ושלום, לזה אמר על פני פירוש כל הווה בעולם הוא על פני כי עיני ה' משוטטים בכל הארץ:
@55 **עוד** ירצה לתת טעם לאזהרתו כי כפי שכל אנושי ירחיק הדבר מטעם כי כל עובד אינו עובד אלא לאחד ממשמשיו יתברך ואדרבה מגדולת העבד גדולת האדון נודעת ואם כן העובד לשמש ולירח הרי זה עובד עבדיו ומשמשיו יתברך ולמה יקפיד ה' על הדבר, לזה אמר **על פני** פירוש לסיבה שאני מתכעס על הדבר שמשימים אל ללא אל, ותיבת פני לשון כעס על דרך אומרו (לקמן ל''ג י''ד) פני ילכו וגו', וכמו שאמר לבסוף כי אנכי וגו' אל קנא:
@55 **עוד** ירצה **על פני** על סיבת פני לבל תהיו נמנעים מהביט אל האלהים, כי אין לך עונג בעולם כראות פני ה' בעולם הנשמות כי הוא זה תכלית המקווה, והזהירם ה' לבל יסבבו מניעת עצמם מהשגה זו:
@55 **עוד** ירצה על דרך אומרו (דברים כח י) וראו כל עמי הארץ כי שם ה' נקרא עליך, ומעתה כשעובד אלהים אחרים הנה הוא משרה בחינת הרע על הפנים אשר שם קנתה הקדושה מקומה:
@56 **לא תעשה לך פסל וגו'**. צריך לדעת אחר אומרו לא יהיה לך וגו' ואפילו במחשבה מה צורך עוד לצוות על מעשה הפסילים, ואם לצוות על עשייתם אפי' לזולת אם כן לא היה לו לומר תיבת לך. עוד לא הי' לו לגמור אומר **לא תשתחוה** אם לא באה האזהרה אלא על מעשה אומן. עוד למה קרא לצלמים בשם פסל. עוד צריך לדעת למה הוצרך לומר פעם אחרת ה' **אלהיך** שהיה מספיק לומר כי אנכי אל קנא וחוזרים הדברים להמדבר בתחלה אנכי ה' אלהיך. עוד צריך לדעת למה הוצרך לתת טעם **כי** וגו' אל קנא הלא בלא טעם זה יתחייבו לקבל גזירת מלכו של עולם ברוך הוא:
@56 **ונראה** שיכוין לומר איסור מין עבודה זרה חוץ מהמוזכר בפסוק לא יהיה לך, והוא כי יאמר אדם האמת כי ה' הוא האלהים וכל זולתו אין אבל לצד עוצם גדולתו תתמעט תכונת האדם והשגתו לדבר לפניו ולשאול פרטי שאלותיו כי אינו ממוסר גדר הכבוד שתבא בריה שפלה אפילה כמוני ותשאל שאלות מלפני המלך הגדול והנורא ולפעמים ירבה בפרטי צרכיו דקים ורבים ואיך יהיה לו כל כך עזות פנים להרבות לשאול דקדוקי השאלות, אשר על כן יתיעץ בדעת יצרו שיבחר לדבר דבריו לפני אחד ממשמשי עליון המשמשים לפניו במרום והוא יעזור לו גם יהיה אמצעי לדבר דבריו לפני המלך הגדול בדבר הגדול אם יצטרך ובאמצעות כן כבד יכבד את השמש ההוא ויברכהו וישתחוה לפניו בדרך כל הכבוד והמעלה שבזה יתרצה לשאת משאו עליו לעשות לו צרכיו. ודע כי טעות זה בה טעו רוב העובדים עבודה זרה כי יודעים הם שעובדים ללא אלוה אלא כדי שיהיה להם לאמצעי וכו' כנזכר, ובחינה זו לא יקרא לה שם אלוה אלא פסל כי הוא יודע כי לא אלוה הוא וזה הוא פסלותו שאין בו כח אלהי ופסולת הוא לפני העיקר שהוא הבורא עולם, או קראו **פסל** כי הוא עומד להתפסל כשיעבירנו ה' מממשלתו על ידי סיבה או על ידי סיבת זה המשתחוה לו שיהא גורם להתפסל על דרך אומרם ז''ל (איכה רבתי פ''ב) במעשה דור המבול שאמרו אנו משביעים לשרים הממונים וכו' וה' העביר ממשלת השרים כאומרו (ישעי' מ''ג) ואחלל שרי קודש. וצוה ה' גם על בחינה זו ואמר **לא תעשה לך** פסל פירוש הגם כי לך בעצמך בדעתך שהוא פסל אף על פי כן לא תעשהו לך וחזר ופירש מה הוא המעשה ואמר **לא תשתחוה להם** וגו' ואמר הטעם להאיסור **כי אנכי ה' אל קנא** פירוש מתקנא אני על הדבר הגם שיהיה בדרך זה. ולהבין תוכן הכוונה הנה מצינו לה' שהזכיר פרט זה של הקנאה בפרשת נשא (במדבר י''ד) דכתיב ועבר עליו רוח קנאה וקנא את אשתו וגו' הנה לפעמים יתקנא אדם באשתו על בנו ועל עבדו, וכבר ידעת כי ישראל בבחינת כלה הם כרמוז באורך בספר קודש קדשים שיר השירים, ומעתה כשישראל עושים להם בעלים הגם שלא ימרדו ולא יכחידו בבורא כי הוא אדון האדונים, השכל יחייב כי יתקנא הבעל. והמשל בזה אשת מלך כי תאהוב עבד מלך או בנו להכין דקדוקי פרטים הצריכה להם ותחבקהו ותנשקהו האם לא יתקנא המלך לדוקרה בחרב, כמו כן הדבר הזה, והמבחין אופן דביקות נפש עם בני ישראל עם הבורא בחפיצה בחשיקה בדביקה באהבה רבה ישיג התבוננות המושכל, והוא מה שאמר כי **אנכי ה' אלהיך** דקדק לומר אלהיך לרמוז האמור והוא סוד השראת שכינתו יתברך על ישראל וייחוד שמו והמשכיל יבין. ולזה תמצא כי אמר הכתוב (דברים ד יט) אשר חלק ה' וגו' לכל העמים כי העמים שריהם שרי מעלה והם המושלים בהם לא כן בני ישראל הוא מלכנו הוא שרינו הוא אלהינו ברוך הוא:
@56 **ובדרך** רמז ירמוז אומרו **לא תעשה לך פסל** פירוש שלא יפסול את עצמו, כי בחטא האדם בעון עבודה זרה שהיא כנגד כל התורה כולה מטבעו נפסל ויוסר צלם אלהי דכתיב (תהלים ל''ט) אך בצלם יתהלך איש ולא יראו פניו למעלה ונכנם בגדר איסור לבני אל חי לבל יסתכלו בפניו כמאמר הנביא למלך ישראל (מ''ב ג') לולי פני יהושפט וגו':
@57 **פקד עון אבות וגו'**. פירוש לצד כי אמר שהוא קנאי ברוך הוא וידוע הוא כי הקנאות תפעיל סמוך לדבר המתקנא עליו ורואים אנו הכחשת הדבר חס ושלום כמה וכמה מרדו ופשעו ועשו והצליחו ולא נגעה יד הקנאי, לזה אמר **פוקד** פירוש ואם ראית הפכיות הקנאה דע כי אני פוקד פירוש זו היא מדתי שאין אני נפרע מעושי רשע מיד ומאריך אפי עד דור ב' וג' וד' פירוש לפעמים. ואין אני מאריך אפי אלא עד זמן זה, והטעם כי אם היה ה' מתקנא לאדם תכף אין קיום לנבראים, לזה מתחכם ה' לעושי רשעה ומעלים עין מלאבדם בעולם הזה כדי שיקומו בניהם אולי יטיבו דרכיהם ונמצא עולם קיים בהם, גם יועיל לאבות לזכותם בעולם הבא כאומרם (סנהדרין ק''ד.) ברא מזכה אבא, ואם דור ב' התעיבו כמעשה אבות אז יפקוד עליהם עון אבותם אתם ימקו, ועדיין ישנו לקנאות רשע האב בפרעון הבנים. ולפעמים יוסיף ה' להאריך אפו גם לדור ב' ותולה להם עד דור ג' לטעם עצמו האמור וכשירשיעו יפקוד עליהם וכו', ולפעמים יוסיף גם כן להאריך אפו גם לדור ג', אבל דור רביעי אין עוד תקוה להם כי הושרשו בקליפה לא ינתקו ממנה ובערה בם קנאת ה' עונם ועון אבות אבות אבותם מדור ראשון יחרב, והטעם כי כולם בחינת רע שלשלת אחת. ואשכילך כי בערך האדון ברוך הוא אפילו כשיאריך אפו עד דור רביעי יקרא מיד, כי ג' וד' דורות הם ג' מאות שנה ויומו של הקדוש ברוך הוא אלף שנה וכמו שיאמר תכף ומיד בערך האדם ו' וז' שעות כמו כן יהיה בערך האדון ג' מאות שנה. ובזה תמצא ישוב טעם למה האריך ה' לומר **על ועל** ולא אמר בדרך כלל פוקד עון עד רבעים כאומרו בעושה חסד לאלפים, כי ישתנה זה מזה והבן ועיין בסמוך:
@57 **ודע** כי התבוננות בדבר זה שאין ה' מתקנא בעושי רשע הוא דבר מבהיל ומה גם רשע מאריך ברשעתו ומצליח ברום ההצלחות, והמשכיל בגדר אשר גבל הבורא שהוא לד' דורות יצדיק משפט ישר, והוא שאמר אסף (תהלים ע''ג) אבינה לאחריתם פי' אחרית קצבת הדורות אשר קצב ה'. ודע כי כח בחי' הרע ישנו עד ד' דורות ולא יפרע ה' מדור ה' עון אבות הראשונים שהוא חמישי להם מה שאין כן בחינת הטוב שתגדל עד אלף ואלפים:
@58 **ועושה חסד לאלפים וגו** '. פירוש שגם עושה חסד אין הקדוש ברוך הוא משלם לו כל חסדו תיכף ומיד אלא בוחר לו אופן פרעון הנאות לו לדורות והולך ופורע בכל דור אשר יצטרך אליו ויש בו דבר המעמיד הגנה והצלה עד אלפים, והוא מאמרם ז''ל (שמו''ר פמ''ד) שאם היה הקדוש ברוך הוא פורע לאבות שכרם בעולם הזה במה היו מתפרנסים בניהם בכל דור ודור ובגליות. ואומרו **ולשומרי מצותי** פירושו רבותינו ז''ל (סוטה ל''א.) שאינה נמשכת עם לאלפים כי אלו שהם עובדים מיראה אם יצטרכו הדורות לזכותו לא יאריך אלא עד אלף כמו שמפורש בפסוק אחר דכתיב (דברים ז ט) לאלף דור וגו':
@59 **לא תשא וגו'**. פי' לצד כי השבועה תגיד גדולות ונשיאות לה' יחשוב אדם כי ישבע בשמו יתברך לכבוד ולתפארת כי הוא זה רבונו ושליטו הגם שיהיה לשוא מה בכך אם הנשבע לו לא יכיר בשקרו כי אם ידע שהוא אדונו של זה והוא באופן שלא יתגלה ההפך, לזה אמר **לא תשא** אפילו יש נשיאות לשם שאתה נשבע בו, **כי לא ינקה ה'** הגם שתהיה כונתו לשאת את שמו, כיון שהוא לשוא:
@59 **עוד** ירצה כי באמצעות שבועת שוא הוא נושא מעליו שם ה' הנקרא עליו ומתלבש בבחינת הרע המתיחסת בשם שוא כי שם ה' אמת והמזכירו בשקר פורח ממנו בחינת השם לסיבת בוחרו בשוא, וזה הוא שיעור הכתוב **לא תשא** מעליך **שם ה' אלהיך** לסיבת שוא, ואמר **כי לא ינקה ה'** לעושי כן:
@59 **עוד** ירמוז שלא יהיה נושא עליו שם ה' שהוא אלוהו ואומר לכל שהוא איש יהודי ועובד ה', והוא אומרו **שם ה'** שהוא **אלהיך** ולבבו לא כן יחשוב, והוא אומרו **לשוא**, ואזהרה זו שלא ירמה ברוך הוא לומר כי הוא מעבדיו ולא כן הוא. ובכלל אזהרה זו שלא יראה על עצמו שהוא צדיק יותר ממה שהוא:
@60 **זכור את יום השבת וגו'**. פירוש שיזכרהו מיום א', ולזה הקדים המאוחר כי מן הראוי היה להקדים לומר ששת ימים וגו' ואחר כך יאמר זכור, אלא נתכוין לומר שהזכירה תהיה מיום ראשון על דרך אומרם ז''ל (מכילתא) שכל יום יאמר היום יום א' בשבת וכו' פירוש ובזה יקדשו ולא יטעה בו. גם ירצה **לקדשו** לשון הזמנה על דרך אומרם ז''ל (ביצה ט''ז) מחד בשבא לשבא, גם ירצה על דרך אומרם ז''ל (מדרש תהלים פצ''ב) כי יום ששי שבו נברא אדם הראשון וחטא ויצא חייב בדינו בא יום שבת ונעשה סניגור לאדם לפני ה' ואמר רבון העולם לא נהרג אדם מעולם וכי אני מתחיל וכו' וניצול אדם וכשראה אדם כחה של שבת התחיל לשורר מזמור שיר ליום השבת, לזה אמר ה' **זכור** פירוש שיזכור את יום השבת אשר באמצעותו נתקיים אדם ויוצאי חלציו וראוי להחשיבו כי הוא דבר המעמיד לכל איש ישראל ויקדשו. ותמצא כי מי שנעשה לו נם ביום אחד יהיה היום ההוא מכובד וחשוב בעיניו תמיד מדי שנה בשנה, וזה יותר על בחינה זו שהשבת עצמו הוא המציל, ולזה אמר **זכור** להיות הדבר רחוק מששת ימי בראשית. עוד ירצה על זה הדרך **זכור את יום השבת** פירוש הזכיר שמו של שבת והטעם **לקדשו** כי כשאתה מזכיר שמו של שבת ביום זה בזה אתה מקדשו, וזה הוא שיעור הכתוב **זכור את יום**, ומה יזכור, שבת; וטעם **לקדשו** כי שמו של הקדוש ברוך הוא שבת כמאמר רשב''י (זהר ח''ב פ''ח:), ואח''כ ביאר הכתוב מה יום מימים ואמר **ששת ימים** וגו' **כי ששת ימים** וגו' הא למדת כי על יום ז' של ששת ימי בראשית הוא אומר:
@61 **ששת ימים תעבוד וגו'**. צריך לדעת לאיזה ענין יצו ה' לעבוד בששת ימים. גם מה היא כוונתו באומרו **ועשית** וגו'. ונראה כי יכוין על דרך מאמר הכתוב בפרשת בהר סיני (ויקרא כ''ה כ') וכי תאמרו מה נאכל בשנה השביעית וגו' וצויתי וגו', והם הדברים הנאמרים כאן לפי מה שקדם לומר זכור את יום השבת לקדשו שאין בו דברי חול אם כן העושה ואוכל דבר יום ביומו מה יאכל ביום המקודש, לזה אמר **ששת ימים** לבד **תעבוד** ובהם תעשה **כל מלאכתך** פירוש הצריכה לך לששי ולשביעי על דרך אומרו (שם) ועשת את התבואה לשלש וגו' כי מבטיח ה' לשומרי מצותיו. עוד ירצה לצוות לבל יחשוב במלאכת חול בשבת, והוא אומרו **ששת ימים** וגו' ויהיה בעיניך כאלו עשית כבר כל מלאכתך שיש לך לעשות, והוא על דרך אומרם ז''ל (מכילתא) שבות כאלו מלאכתך עשויה, שזולת זה יחשוב מחשבות לכונן מלאכתו ואשר יחסר מהמלאכה לעשותה בחול, וצא ולמד ממעשה החסיד (שבת ק''נ:) שקנס עצמו על אשר חשב לגדור גדר נפרץ בשבת לבל יבנהו עוד וכו':
@62 **ויום השביעי וגו'**. פירוש כי בעשותו שבת לה' בזה אתה עושה ה' כי הוא אלהיך על דרך אומרם ז''ל (שמו''ר פכ''ה) כי שקול שבת ככל התורה כולה. ואולי כי רמוזה היא כל התורה בתיבת שבת על זה הדרך תרי''א הם מצות שלא שמעום מפי הגבורה אלא מפי נביא וב' מצות אנכי ולא יהיה לך שהם ב' מצות שנצטוו מפי הגבורה מצות אנכי היא מצות עשה ולא יהיה לך היא מצות לא תעשה, וכבר הודיעונו רבותינו ז''ל כי מצות עשה יתכנו לשם הרחמים לפי שהם בבחינת קבלת שכר ומצות לא תעשה יתכנו לשם אדני לפי שהם בבחינת הדין לעובר עליהם, והנה חשבון הוי''ה אדנ''י עולה צ''א ותרי''א הרי שבת:
@62 **עוד** ירצה על דרך אומרם במס' שבת (קי''ח:) כל השומר שבת כהלכתו אפי' עובד עבודה זרה כאנוש מוחלין לו, והוא אומרו **ויום השביעי שבת** לה' בזה נעשה הוא **אלהיך** ולא זולתו הא למדת שנמחל לו מה שקבל לאלוה זולתו יתברך:
@62 **עוד** ירצה באומרו **שבת לה'** כי לא תהיה המנוחה והשביתה למנוחתו ולמרגועו אלא למצות ה' אלהיו:
@62 **עוד** ירצה על זה הדרך **ששת ימים תעבוד** וגו' **ויום השביעי** גם כן יהיה לך מלאכה אחת ומה היא שאתה עושה שבת לה' אלהיך ולא מיעטתי לך יום השביעי אלא ממלאכתך של עצמך:
@63 **וינח ביום השביעי**. כאן נתחכם ה' לאסור מלאכות אשר מנו חכמים מ' מלאכות [ח''א] שיש בהם מלאכה שאין בה שום טורח כלל בעשייתה כמו שתאמר המוציא כלי מרשות היחיד לרשות הרבים או להפך וכדומה לזה רבים וחייבה התורה מיתה עליהם, ויאמר אדם מה טורח יש בדבר זה להתחייב לזה אמר הכתוב **כי ששת ימים** וגו' **וינח** וגו' פירוש ודוק והשכיל בטעם ותדע כי אין הדבר לצד הטורח לבד והרי מי שנאמר בו (ישעי' מ') לא ייעף ולא ייגע ובו לא יוצדק לומר מנוחה אלא הכוונה היא לצד הפעולה היוצאת אנו דנים הגם שלא תהיה בה יגיעה וטורח, ולזה כל ששם מלאכה עליה הגם כי יעשנה אדם בלא הרגשת דבר הרי זה חייב עליה:
@63 **עוד** ירצה על זה הדרך **כי ששת ימים עשה ה'** וגו' פירוש כי לא עשה בתכונת בריאתם שיעמדו אלא ששת ימים, ומעתה יצטרך ה' לחדש הבריאה בכל יום ובאמצעות נפש העולם שהוא השבת שברא ה' נח מהתמדת המלאכה, וכמאמרם ז''ל (ב''ר פ''י) שהיה העולם רופף ורועד ובבא שבת עמד בקיומו, והוא אומרו **וינח ביום הז'** ויום זה מעמיד העולם עוד ששת ימים ובכל יום ששי לערב שכלתה תכונת העולם יבא שבת ויקיים העולם עוד ששת ימים אחרים וכן על זה הדרך, ועיין פרשת בראשית (ב' ב'):
@64 **למען יאריכון**. אמר **יאריכון** שמשמע מעצמם ולא אמר אאריך ימיך. אולי שירצה לומר כי מצוה זו סגולתה היא אריכות ימים מלבד שכרה מה', כי יש מצות שיש בהם סגולות נפלאות מלבד שכר אשר קבע להם ה' וזו גילה אותה ה':
@68 **דבר וגו'**. פירוש ואם לצד כי כשידבר ה' עמנו נקבל גזירותיו, מעתה הרי אנו מקבלין ממך ואם כן אין צורך בדבר ולמה נסתכן והוא אומרו **פן נמות**. עוד ירצה על זה הדרך **דבר אתה עמנו ונשמעה** פירוש יהיה כח בנו לשמוע אבל אם ידבר ה' עמנו פן נמות ולא נשמע:
@69 **אל תיראו**. פירוש שידבר עמכם עוד **כי לבעבור** וגו' וכבר עשה ה' מחשבתו הטובה ועשה אתכם נס שהם מובדלים לטובה כי פסקה זוהמתם באמצעות דבר האלהים, וגם טעם ב' **בעבור תהיה** וגו' פירוש כי בעקירת הזוהמא מהם הנה קנתה היראה שהיא שכינתו יתברך מקום להיות בתמידות על פניהם כי צלם אלהי אשר יצר ה' את האדם בצלמו חזר לקדמותו, והרווחת ב' דברים אלו הוא לבלתי תחטאו כי כל מי שיש לו בושת פנים שהיא יראתו האמורה לא במהרה הוא חוטא. עוד ירצה באומרו **לבעבור נסות אתכם** כדי שלא תהיה לכם טענה למה לא ינבא ה' את כל ישראל, הרי ניסה אותם בנבואה ולא יכלו עמוד:
@72 **לא תעשון אתי וגו'**. צריך לדעת אומרו תיבת **אתי**. ורבותינו ז''ל (מכילתא) דרשו שלא יעשו הכרובים ד', והוא אומרו **אלהי זהב** שמעלה עליהם כאלו עשו אלהי זהב, ולא יעשו הב' של כסף ואם עשו מעלה עליהם וכו', גם שלא יעשו צורה לדמיון ה' להשתחוות לה (ר''ה כ''ד.) וכוונתם לה' ולא צורת שמשים של ה'. ונראה לפרש הכתוב בדקדוק עוד למה חזר לומר פעם ב' **לא תעשו לכם** ולא הספיק במה שקדם לומר לא תעשון אתי וגו'. עוד למה דקדק לומר תיבת **לכם**:
@72 **אכן** יכוין ה' לצוות על ב' מיני עבודות אל אחר, האחד הוא העובד באמונת לבו כי מאמין בה וכוסף לעובדה, וכנגדה אמר **לא תעשו** ן **אתי אלהי כסף** פירוש אלהי בכוסף וזה יורה על העובד מאמונת לבו. ודקדק לומר **אתי** כי העובד עבודה זרה ברצון נפשו הוא ממשיך בשורש נפשו בחינת הרע שבשורש העון ההוא והוא סוד (איכה ר' פ''א) נחש המקנן במגדל, כי כבר הודיענו הכתוב כי נפשות ישראל חלק אלוה ממעל דכתיב (דברים לב ט) חלק ה' עמו ובעובדו לעבודה זרה באמונת נפשו נותן מקום לס''מ ליכנס במקום שורש הנפש ההיא שהוא מקום הקדושה, והוא שאמר שלמה (משלי ל) תחת עבד כי ימלוך, והוא אומרו **לא תעשון אתי**, ואמר **אלהי כסף** פירוש לשון כוסף שהוא עובדו מכוספו בו רחמנא ליצלן. והב' היודע בלבו אמונה שלימה כי הכל הוא צואה בלי מקום אבל עובדה לסיבת הנאה להנאת המועיל כמו שתאמר שיתנו לו ממון על מנת לעובדה, ויאמר האדם בלבו רחמנא לבא בעי ובלבי אני מחרף ומגדף בעבודה זרה זו ואין מעשי אלא לתכלית הריוח, וכנגד זה אמר **ואלהי זהב לא תעשו לכם** פירוש הגם שאין לבו ונפשו מאמינים בה דבר אלא לצד שזה אהב הזהב ובשביל הנאת זהבו הוא משתחוה אף על פי כן לא תעשו, וגילה שחטא זה הוא דוקא בבחינת האדם שהוא פוגם עצמו וממעיט דיוקנו, והוא אומרו **לכם** לצד שלא חטא אלא במעשה והמחשבה מנגדת כגלוי לפני יודע תעלומות, לזה לא יעשה החטא סיבה שתכניע בחינת הרע את בחינת הטוב כמעשה הראשון:
@72 **חסלת פרשת יתרו**
